seed; return std::hash&lt;std::string&gt;(p.first + p.second);// &lt;functional&gt; 标准类型的哈希函数 } }; std::unordered_map&lt;std::pair&lt;std::string,std::string&gt;,xxx,hash_object&gt; um; map(lambda自定义规则) struct { bool operator()(const int l, const int r) const { return l &gt; r; } } customLess;// class也ok, 用大于变为降序排序，map默认升序 std::map&lt;int,xxx,customLess&gt; m; 最近最少使用缓存(LRU) splice是链表节点快速交换接口 新节点在本链表的期望位置，待插入节点所属链表对象，待插入节点迭代器
频率最低缓存(LFU) // 缓存的节点信息 // 优先淘汰访问频率最低元素 关心历史访问次数 // key_table键到节点映射 freq_table频率到对应频率到双向链表映射，同频率使用同一list按访问时间排序类似lru struct Node { int key, val, freq; Node(int _key,int _val,int _freq): key(_key), val(_val), freq(_freq){} }; class LFUCache { int minfreq, capacity; unordered_map&lt;int, list&lt;Node&gt;::iterator&gt; key_table; unordered_map&lt;int, list&lt;Node&gt;&gt; freq_table; public: LFUCache(int _capacity) { minfreq = 0; capacity = _capacity; key_table.clear(); freq_table.clear(); } int get(int key) { if (capacity == 0) return -1; auto it = key_table.find(key); if (it == key_table.end()) return -1; list&lt;Node&gt;::iterator node = it -&gt; second; int val = node -&gt; val, freq = node -&gt; freq; freq_table[freq].erase(node); // 如果当前链表为空，我们需要在哈希表中删除，且更新minFreq if (freq_table[freq].size() == 0) { freq_table.erase(freq); if (minfreq == freq) minfreq += 1; } // 插入到 freq + 1 中 freq_table[freq + 1].push_front(Node(key, val, freq + 1)); key_table[key] = freq_table[freq + 1].begin(); return val; } void put(int key, int value) { if (capacity == 0) return; auto it = key_table.find(key); if (it == key_table.end()) { // 缓存已满，需要进行删除操作 if (key_table.size() == capacity) { // 通过 minFreq 拿到 freq_table[minFreq] 链表的末尾节点 auto it2 = freq_table[minfreq].back(); key_table.erase(it2.key); freq_table[minfreq].pop_back(); if (freq_table[minfreq].size() == 0) { freq_table.erase(minfreq); } } freq_table[1].push_front(Node(key, value, 1)); key_table[key] = freq_table[1].begin(); minfreq = 1; } else { // 与 get 操作基本一致，除了需要更新缓存的值 list&lt;Node&gt;::iterator node = it -&gt; second; int freq = node -&gt; freq; freq_table[freq].erase(node); if (freq_table[freq].size() == 0) { freq_table.erase(freq); if (minfreq == freq) minfreq += 1; } freq_table[freq + 1].push_front(Node(key, value, freq + 1)); key_table[key] = freq_table[freq + 1].begin(); } } }; 并查集 class UnionFindSet{ private: std::vector&lt;size_t&gt; parent_; std::vector&lt;size_t&gt; rank_; // 集合根节点深度 public: UnionFindSet(size_t n):parent_(n),rank_(n,1) { for(size_t i = 0;i &lt; n;++i) { parent_[i] = i; } } // 递归压缩 size_t FindRoot(size_t x) { // 递归路径压缩 if(parent_[x] == x) return x; parent_[x] = FindRoot(parent_[x]); // 递归到最深找到集合根节点，在回溯时会统一将路径上的所有节点的父节点压缩为集合根节点 return parent_[x]; } // // 迭代隔代压缩，没有递归太深爆栈的风险 // size_t FindRoot(size_t x) // { // while (parent_[x] != x) { // parent_[x] = parent_[parent_[x]]; // x = parent_[x]; // } // return x; // } // // 迭代全压缩 // size_t FindRoot(size_t x) { // size_t root = x; // while (parent_[root] != root) { // root = parent_[root]; // } // // 路径压缩，把x到root路径上的所有节点的父节点设为root // while (parent_[x] != root) { // size_t prev = parent_[x]; // parent_[x] = root; // x = prev; // } // return root; // } // 没有按秩合并的可能导致的问题 // 假设每次合并时随意将一棵树附加到另一棵树： // 0 0 // \ \ // 1 1 // \ \ // 2 合并以3为根的子树 2 // \ \ // 3 3 // \ // ... (可能退化为链表) // 通过比较秩（树高），总是将较矮的树合并到较高的树： // 树高不会超过 log₂n.结合路径压缩后，find 操作的摊还时间复杂度接近 O(α(n))（反阿克曼函数，几乎为常数） void Union(size_t x,size_t y){ size_t x_root = FindRoot(x); size_t y_root = FindRoot(y); if(x_root == y_root) return; // 保证森林结构平衡，加快查询根的速度 // 两棵树高度不同时，将矮树合并到高树下，高度不变；若高度相同，合并后树高加1 if(rank_[x_root] &lt; rank_[y_root]) { parent_[x_root] = y_root; } else { parent_[y_root] = x_root; // 高度相同，总高+1 if (rank_[x_root] == rank_[y_root]) ++rank_[x_root]; } } bool Union(size_t x,size_t y){ size_t x_root = FindRoot(x); size_t y_root = FindRoot(y); if(x_root == y_root) return false; // 保证森林结构平衡，加快查询根的速度 // 两棵树高度不同时，将矮树合并到高树下，高度不变；若高度相同，合并后树高加1 if(rank_[x_root] &lt; rank_[y_root]) { parent_[x_root] = y_root; } else { parent_[y_root] = x_root; // 高度相同，总高+1 if (rank_[x_root] == rank_[y_root]) ++rank_[x_root]; } return true; } bool connected(size_t x,size_t y) { return FindRoot(x) == FindRoot(y);} }; 最小生成树 #include &lt;iostream&gt; #include &lt;vector&gt; #include &lt;queue&gt; #include &lt;algorithm&gt; using namespace std; // ====================== 通用数据结构 ====================== struct Edge { int u, v, weight; Edge(int u, int v, int w) : u(u), v(v), weight(w) {} }; // kruskal // 输入边表和顶点数n vector&lt;Edge&gt; kruskalMST(vector&lt;Edge&gt;&amp; edges, int n) { sort(edges.begin(), edges.end(), [](const Edge&amp; a, const Edge&amp; b) { return a.weight &lt; b.weight; // 按权重升序排序 }); // 贪心优先将权重小的加入生成树中 UnionFindSet uf(n); vector&lt;Edge&gt; mst; for (const Edge&amp; e : edges) { // 树不允许存在环，通过并查集检查是否存在环 // 按顺序将边加入并查集，当出现环后(当一条边的两个节点都属于同一集合则说明出现环) if (uf.Union(e.u, e.v)) { mst.push_back(e); if (mst.size() == n - 1) break; // 已找到足够边 } } return mst; } // ====================== Prim 算法实现 ====================== // 输入邻接表(稠密) // 其原理本质是BFS泛洪用visited避免结果中存在环，则保证结果连通的树结构，并基于优先队列保证为最小权重树 vector&lt;Edge&gt; primMSTFullEdge(const vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt;&amp; adj) { int n = adj.size(); vector&lt;bool&gt; visited(n, false); // 使用三元组存储：权重、源节点、目标节点 using EdgeTuple = tuple&lt;int, int, int&gt;; priority_queue&lt;EdgeTuple, vector&lt;EdgeTuple&gt;, greater&lt;&gt;&gt; pq; // 最小堆 vector&lt;Edge&gt; mst; int start = 0; visited[start] = true; // 初始化：将起始节点的所有邻接边加入队列 for (const auto&amp; [v, w] : adj[start]) { pq.emplace(w, start, v); // (weight, src, dest) } while (!pq.empty() &amp;&amp; mst.size() &lt; n - 1) { auto [weight, src, dest] = pq.top(); pq.pop(); if (visited[dest]) continue; // 目标节点已在生成树中 // 记录完整边信息 mst.emplace_back(src, dest, weight); visited[dest] = true; // 将目标节点的邻接边加入队列（源节点为当前目标节点） for (const auto&amp; [v, w] : adj[dest]) { if (!visited[v]) { pq.emplace(w, dest, v); // (weight, src=dest, dest=v) } } } return mst; } 拓扑排序 有向无环图排序，若原图中i指向j则排序结果中i一定在j之前。用于带约束排序问题，某个条件必须被满足才能选择另一节点 or &hellip;。
