#include &lt;vector&gt; #include &lt;queue&gt; using namespace std; struct Edge { int u, v, weight; Edge(int u, int v, int w) : u(u), v(v), weight(w) {} }; // 节点为string vector&lt;string&gt; topologicalSort(const unordered_map&lt;string, unordered_set&lt;string&gt;&gt;&amp; edges) { // Step 1: 收集所有节点并初始化数据结构 unordered_set&lt;string&gt; nodes; unordered_map&lt;string, int&gt; inDegree; // 收集所有节点并构建邻接表 for (const auto&amp; [u, neighbors] : edges) { nodes.insert(u); // 添加源节点 // 添加目标节点并初始化入度 for (const auto&amp; v : neighbors) { nodes.insert(v); inDegree[v] = 0; // 确保所有节点都有入度记录 } } // 初始化入度表（显式遍历保证覆盖孤立节点） for (const auto&amp; node : nodes) { inDegree[node] = 0; // 确保所有节点都有入度记录 } // Step 2: 计算入度 for (const auto&amp; [u, neighbors] : edges) { for (const auto&amp; v : neighbors) { inDegree[v]++; } } // Step 3: Kahn算法核心逻辑 queue&lt;string&gt; q; for (const auto&amp; node : nodes) { // 当v的入度==0相当于，v的所有前置条件已满足可加入结果中 if (inDegree[node] == 0) q.push(node); // 入度为0，相当于优先级最高节点加入队列中 } vector&lt;string&gt; order; while (!q.empty()) { string u = q.front(); q.pop(); order.push_back(u); // 加入结果 // 处理邻接节点（需要检查是否存在邻接关系） if (edges.find(u) != edges.end()) { for (const auto&amp; v : edges.at(u)) { if (--inDegree[v] == 0) { // 移除u-&gt;v边 -- v的入度-1.当v的入度==0相当于，v的所有前置条件已满足可加入结果中 q.push(v); } } } } // Step 4: 环检测 return (order.size() == nodes.size()) ? order : vector&lt;string&gt;(); } 二分图 偶(双图、二部图)，两种事物间的连接关系，图中节点被分为两类，同类别的顶点间不存在边(边只存在于不同类别的顶点)。具有二分类(X,Y)偶图是指，图的顶点集合可被分解为两个非空子集X和Y,使得每条边的一个端点在X中另一端点在Y中。允许有重边
#include &lt;vector&gt; #include &lt;queue&gt; using namespace std; // 时间O(V+E)各个顶点和边只访问一次，空间O(V) // 着色判断二部，如果某条边连通的两节点着相同的色则非二分图 // graph是邻接表表达 bool isBipartite(vector&lt;vector&lt;int&gt;&gt;&amp; graph) { int n = graph.size(); vector&lt;int&gt; color(n, -1); // -1: 未着色, 0/1: 两种颜色 for (int i = 0; i &lt; n; ++i) { if (color[i] != -1) continue; queue&lt;int&gt; q; q.push(i); // 找种子 color[i] = 0; while (!q.empty()) { int u = q.front(); q.pop(); for (int v : graph[u]) { if (color[v] == -1) { // 未着色节点 color[v] = 1 - color[u]; // 连通节点染上另一种颜色 q.push(v); } else if (color[v] == color[u]) { // 连通节点的颜色相同不符合二分图定义 return false; // 冲突，非二分图 } } } } return true; } 字典树(Tire) 用于判断子字符串是否存在或是否具由某种字符串前缀
#include &lt;iostream&gt; #include &lt;unordered_map&gt; #include &lt;memory&gt; using namespace std; class TrieNode { public: unordered_map&lt;char, unique_ptr&lt;TrieNode&gt;&gt; children; // 用 char[256]数组也行 bool isEnd; TrieNode() : isEnd(false) {} }; // 字典树 支持快速插入单词，查找单词，查找具有某前缀的单词 class Trie { private: unique_ptr&lt;TrieNode&gt; root; // 查找公共前缀长度（与之前实现相同） // static int commonPrefix(const string&amp; s1, const string&amp; s2) { // int minLen = min(s1.size(), s2.size()); // for (int i = 0; i &lt; minLen; ++i) { // if (s1[i] != s2[i]) return i; // } // return minLen; // } // // 分割节点（注意参数改为智能指针引用） // void splitNode(unique_ptr&lt;RadixNode&gt;&amp; node, int splitPos) { // string remain = node-&gt;fragment.substr(splitPos); // string original = node-&gt;fragment.substr(0, splitPos); // // 创建新节点接管原有子节点 // auto newNode = make_unique&lt;RadixNode&gt;(remain); // newNode-&gt;children = move(node-&gt;children); // newNode-&gt;isEnd = node-&gt;isEnd; // // 重置当前节点 // node-&gt;fragment = original; // node-&gt;isEnd = false; // node-&gt;children[remain[0]] = move(newNode); // } public: Trie() { root = make_unique&lt;TrieNode&gt;(); } // 移动构造函数 Trie(Trie&amp;&amp; other) noexcept = default; // 移动赋值运算符 Trie&amp; operator=(Trie&amp;&amp; other) noexcept = default; // 禁用拷贝 Trie(const Trie&amp;) = delete; Trie&amp; operator=(const Trie&amp;) = delete; void insert(const string&amp; word) { TrieNode* node = root; for (char c : word) { if (!node-&gt;children.count(c)) { node-&gt;children[c] = make_unique&lt;TrieNode&gt;(); } node = node-&gt;children[c]; } node-&gt;isEnd = true; } bool search(const string&amp; word) { const TrieNode* node = root.get(); for (char c : word) { if (!node-&gt;children.count(c)) return false; node = node-&gt;children[c].get(); } return node-&gt;isEnd; } bool startsWith(const string&amp; prefix) { const TrieNode* node = root.get(); for (char c : prefix) { if (!node-&gt;children.count(c)) return false; node = node-&gt;children[c].get(); } return true; } }; 二叉搜索树(BST) 特殊的完全二叉树，logn查找，要求左子树所有节点值&lt;=父节点&lt;=右子树所有节点值
struct TreeNode { int val; TreeNode* left{nullptr}; TreeNode* right{nullptr}; TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} }; class BST { private: TreeNode* root; // 递归插入实现 TreeNode* insert(TreeNode* node, int val) { if (!node) return new TreeNode(val); if (val &lt; node-&gt;val) { node-&gt;left = insert(node-&gt;left, val); } else if(val &gt; node-&gt;val){ node-&gt;right = insert(node-&gt;right, val); } // val == node-&gt;val,要插入的元素在树中已存在 return node; } // 查找最小值节点 TreeNode* findMin(TreeNode* node) { while (node &amp;&amp; node-&gt;left) node = node-&gt;left; return node; } // 递归删除实现 TreeNode* remove(TreeNode* node, int val) { if (!node) return nullptr; if (val &lt; node-&gt;val) { node-&gt;left = remove(node-&gt;left, val); } else if (val &gt; node-&gt;val) { node-&gt;right = remove(node-&gt;right, val); } else if(node-&gt;left != nullptr &amp;&amp; node-&gt;right != nullptr){ // 当前是要被删除的节点 // 有两个子节点的情况 // 将右子树中的最小节点作为删除后子树的根节点(左子树中的最大节点也行) TreeNode* temp = findMin(node-&gt;right); node-&gt;val = temp-&gt;val; node-&gt;right = remove(node-&gt;right, temp-&gt;val); // 将右子树中最小节点删除 } else { if (!node-&gt;left) { // 要被删除的节点不存在左子树，将右子树替换当前节点 TreeNode* temp = node-&gt;right; delete node; return temp; } else if (!node-&gt;right) { // 要被删除的节点不存在右子树，将左子树替换当前节点 TreeNode* temp = node-&gt;left; delete node; return temp; } } return node; } // 中序遍历 void inorder(TreeNode* node) { if (!node) return; inorder(node-&gt;left); cout &lt;&lt; node-&gt;val &lt;&lt; &#34; &#34;; inorder(node-&gt;right); } public: BST() : root(nullptr) {} void insert(int val) { root = insert(root, val); } bool search(int val) { TreeNode* curr = root; while (curr) { if (val == curr-&gt;val) return true; curr = val &lt; curr-&gt;val ? curr-&gt;left : curr-&gt;right; } return false; } void remove(int val) { root = remove(root, val); } void print() { inorder(root); cout &lt;&lt; endl; } // 析构函数（内存管理） ~BST() { clear(root); } private: void clear(TreeNode* node) { if (!node) return; clear(node-&gt;left); clear(node-&gt;right); delete node; } }; 树的遍历 // DFS void preorder(TreeNode* root) { // 中、左、右 visit(root); // visit可当成cout输出这个节点 preorder(root-&gt;left); preorder(root-&gt;right); } void inorder(TreeNode* root) { // 左、中、右 inorder(root-&gt;left); visit(root); inorder(root-&gt;right); } void postorder(TreeNode* root) { // 左、右、中 postorder(root-&gt;left); postorder(root-&gt;right); visit(root); } // 非递归用栈实现 vector&lt;int&gt; preorderTraversal(TreeNode* root) { vector&lt;int&gt; ret; if (!root) { return ret; } stack&lt;TreeNode*&gt; s; s.push(root); while (!s.empty()) { TreeNode* node = s.top();// 中 s.pop(); ret.push_back(node-&gt;val); // 栈是后入先出，中序是先左再右，所以是先入右再入左 if (node-&gt;right) { s.push(node-&gt;right); // 先右后左，保证左子树先遍历 } if (node-&gt;left) { s.push(node-&gt;left); } } return ret; } vector&lt;int&gt; inorderTraversal(TreeNode* root) { TreeNode* curr = root; vector&lt;int&gt; ret; if (curr == nullptr) { return ret; } stack&lt;TreeNode*&gt; stk; while (!stk.empty() || curr != nullptr) { while (curr != nullptr) { // 左 stk.push(curr); curr = curr-&gt;left; } curr = stk.top(); // 中 ret.push_back(curr-&gt;val); stk.pop(); curr = curr-&gt;right; // 右 } return ret; } vector&lt;int&gt; postorderTraversal(TreeNode* root) { vector&lt;int&gt; res; stack&lt;TreeNode*&gt; stk; TreeNode* curr = root; TreeNode* pre = nullptr; // 记录前一个访问节点 while (curr != nullptr || !stk.empty()) { // 深入左子树到底 while (curr) { // 左 stk.push(curr); curr = curr-&gt;left; } TreeNode* node = stk.top(); // 右子树存在且未被访问 // 因为是左右中，是先遍历右子树，当回到中节点时需要pre检查判断右子树是否已被访问 // 若已被访问不看右子树 if (node-&gt;right != nullptr &amp;&amp; node-&gt;right != pre) { curr = node-&gt;right; // 右 } else { // 中 res.push_back(node-&gt;val); pre = node; // 更新前驱节点 stk.pop(); } } return res; } // BFS层次遍历 vector&lt;int&gt; BFS(TreeNode* root) { vector&lt;int&gt; res; queue&lt;TreeNode*&gt; q; q.emplace(root); // while (!q.empty()) { // auto front = q.front(); // res.emplace_back(front-&gt;val); // if(front-&gt;left != nullptr) // { // q.emplace(front-&gt;left); // } // if(front-&gt;right != nullptr) // { // q.emplace(front-&gt;right); // } // } // 分层输出 while (!q.empty()) { size_t count = q.size(); for (size_t i = 0; i &lt; count; ++i) { // 将当前层节点输出完，并将下层节点加入队列 TreeNode* node = q.front(); q.pop(); res.emplace_back(node-&gt;val); if (node-&gt;left) { q.push(node-&gt;left); } if (node-&gt;right) { q.push(node-&gt;right); } } // 上层输出结束 } return res; } 树的递归 // 104 求树的最大深度 int maxDepth(TreeNode* root) { return root != nullptr? 1 + max(maxDepth(root-&gt;left), maxDepth(root-&gt;right)): 0; } // 110 树是否平衡(左右子树的高度差不超过1) // 主函数 bool isBalanced(TreeNode* root) { return helper(root) != -1; } int helper(TreeNode* root) { if (!root) { return 0; } int left = helper(root-&gt;left), right = helper(root-&gt;right); // 计算左右子树的高度 if (left == -1 || right == -1 || abs(left - right) &gt; 1) { return -1; // 左右子树高度差&gt;1则不可能平衡，返回-1。若左/右的helper返回-1则说明左或右已不平衡，不需要看其他分支提前返回 } return 1 + max(left, right); } // 543 二叉树的最长直径(任意两节点间的无向距离) // 主函数 int diameterOfBinaryTree(TreeNode* root) { int diameter = 0; helper(root, diameter); return diameter; } int helper(TreeNode* node, int&amp; diameter) { if (!node) { return 0; } int l = helper(node-&gt;left, diameter), r = helper(node-&gt;right, diameter); // 返回左右子树的高度 diameter = max(l + r, diameter); // l+r表示此节点的直径 return max(l, r) + 1; } // 437 求右多少条路径/子路径(路径的定义是在每层只能选择一个节点，此节点只能为上层节点的左或右)节点值的和等于给定值 // 主函数 int pathSum(TreeNode* root, int sum) { return root? pathSumStartWithRoot(root, sum) + pathSum(root-&gt;left, sum) + pathSum(root-&gt;right, sum): 0; } int pathSumStartWithRoot(TreeNode* root, int sum) { if (!root) { return 0; } int count = root-&gt;val == sum? 1: 0; count += pathSumStartWithRoot(root-&gt;left, sum - root-&gt;val); // 后继选左 count += pathSumStartWithRoot(root-&gt;right, sum - root-&gt;val); // 后继选右 return count; } // 101 二叉树是否对称(以根节点分成左和右，左右镜像对称) bool isSymmetric(TreeNode *root) { return root? isSymmetric(root-&gt;left, root-&gt;right): true; } bool isSymmetric(TreeNode* left, TreeNode* right) { if (!left &amp;&amp; !right) { // 左右都不存在则以当前根节点，左右对称 return true; } if (!left || !right) { // 一个左或右存在另一个不存在则一定不对称 return false; } if (left-&gt;val != right-&gt;val) { //当前左右对称 return false; } // 当前子节点是否对称拆为，当前的左-&gt;左和右的右相同 且 当前左-&gt;右和右-&gt;左相同 return isSymmetric(left-&gt;left, right-&gt;right) &amp;&amp; isSymmetric(left-&gt;right,right-&gt;left); } // 1110 返回删除树上指定节点后的森林 vector&lt;TreeNode*&gt; delNodes(TreeNode* root, vector&lt;int&gt;&amp; to_delete) { vector&lt;TreeNode*&gt; forest; unordered_set&lt;int&gt; dict(to_delete.begin(), to_delete.end()); // 转哈希快速查询节点是否需要被删 root = helper(root, dict, forest); if (root != nullptr) { forest.push_back(root); } return forest; } TreeNode* helper(TreeNode* root, unordered_set&lt;int&gt; &amp; dict, vector&lt;TreeNode*&gt; &amp; forest) { if (!root) { return root; } // 后续遍历 root-&gt;left = helper(root-&gt;left, dict, forest); // 返回删除后的左子树 root-&gt;right = helper(root-&gt;right, dict, forest); // 返回删除后的右子树 if (dict.count(root-&gt;val)) { // 当前节点要被删 if (root-&gt;left != nullptr) { forest.push_back(root-&gt;left); // 保存左子树 } if (root-&gt;right != nullptr) { forest.push_back(root-&gt;right); // 保存右子树 } root = nullptr;// delete root; root = nullptr; } return root; } 链表 // 206 链表反转 // 递归 ListNode* reverseList(ListNode* head, ListNode* prev=nullptr) { if (!head) { return prev; } ListNode* next = head-&gt;next; head-&gt;next = prev; return reverseList(next, head); } //非递归 ListNode* reverseList(ListNode* head) { ListNode *prev = nullptr, *next; while (head) { next = head-&gt;next; head-&gt;next = prev; prev = head; head = next; } return prev; } // 21 两个升序链表合并为一个升序链表 // 递归 分治 ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) { if (!l2) { return l1; } if (!l1) { return l2; } if (l1-&gt;val &gt; l2-&gt;val) { l2-&gt;next = mergeTwoLists(l1, l2-&gt;next); return l2; } l1-&gt;next = mergeTwoLists(l1-&gt;next, l2); return l1; } // 非递归 ListNode* mergeTwoLists(ListNode *l1, ListNode *l2) { ListNode *dummy = new ListNode(0), *node = dummy; while (l1 &amp;&amp; l2) { if (l1-&gt;val &lt;= l2-&gt;val) { node-&gt;next = l1; l1 = l1-&gt;next; } else { node-&gt;next = l2; l2 = l2-&gt;next; } node = node-&gt;next; } node-&gt;next = l1? l1: l2; return dummy-&gt;next; // delete dummy } // 24 交换链表中的相邻节点 // Input: 1-&gt;2-&gt;3-&gt;4 // Output: 2-&gt;1-&gt;4-&gt;3 ListNode* swapPairs(ListNode* head) { ListNode *p = head, *s; if (p &amp;&amp; p-&gt;next) { // 交换头两个节点 s = p-&gt;next; p-&gt;next = s-&gt;next; s-&gt;next = p; head = s; // 交换后续节点(处理p-&gt;next-&gt;next) while (p-&gt;next &amp;&amp; p-&gt;next-&gt;next) { s = p-&gt;next-&gt;next; p-&gt;next-&gt;next = s-&gt;next; s-&gt;next = p-&gt;next; p-&gt;next = s; p = s-&gt;next; } } return head; } // 160 返回两个链表的第一个交点 // 假设链表 A 的头节点到相交点的距离是 a，链表 B 的头节点到相交点的距离是 b，相交点 // 到链表终点的距离为 c。我们使用两个指针，分别指向两个链表的头节点，并以相同的速度前进， // 若到达链表结尾，则移动到另一条链表的头节点继续前进。按照这种前进方法，两个指针会在 // a + b + c 次前进后同时到达相交节点。 ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) { ListNode *l1 = headA, *l2 = headB; while (l1 != l2) { l1 = l1? l1-&gt;next: headB; l2 = l2? l2-&gt;next: headA; } return l1; } // 234 链表回文判断 // 先使用快慢指针找到链表中点，再把链表切成两半；然后把后半段翻转；最后比较两半是否相等。 bool isPalindrome(ListNode* head) { if (!head || !head-&gt;next) { return true; } // 快慢指针找到中点 ListNode *slow = head, *fast = head; while (fast-&gt;next &amp;&amp; fast-&gt;next-&gt;next) { slow = slow-&gt;next; fast = fast-&gt;next-&gt;next; } // slow此时为中点 slow-&gt;next = reverseList(slow-&gt;next); slow = slow-&gt;next; // 同时步进比较链表是否相同 while (slow != nullptr) { if (head-&gt;val != slow-&gt;val) { return false; } head = head-&gt;next; slow = slow-&gt;next; } return true; } // 辅函数 ListNode* reverseList(ListNode* head) { ListNode *prev = nullptr, *next; while (head) { next = head-&gt;next; head-&gt;next = prev; prev = head; head = next; } return prev; } 字符串 // 205 字符串同构 // 判断两个字符串是否同构。同构的定义是，可以通过把一个字符串的某些相同的字符转换成 // 另一些相同的字符，使得两个字符串相同，且两种不同的字符不能够被转换成同一种字符。 // Input: s = &#34;paper&#34;, t = &#34;title&#34; // Output: true bool isIsomorphic(string s, string t) { if(s.size() != t.size()) return false; vector&lt;int&gt; s_first_index(256, 0), t_first_index(256, 0); // 记录两个字符串每个位置的字符上一次出现的位置，如果两个字 // 符串中相同位置的字符与它们上一次出现的位置一样，那么这两个字符串同构 for (int i = 0; i &lt; s.length(); ++i) { if (s_first_index[s[i]] != t_first_index[t[i]]) { return false; } s_first_index[s[i]] = t_first_index[t[i]] = i + 1; } return true; } // 647 输出字符串的所有回文串数量 // Input: &#34;aaa&#34; // Output: 6 // 六个回文子字符串分别是 [&#34;a&#34;,&#34;a&#34;,&#34;a&#34;,&#34;aa&#34;,&#34;aa&#34;,&#34;aaa&#34;] int countSubstrings(string s) { int count = 0; // 从字符串的每个位置开始，向左向右延长，判断存在多少以当前位置为中轴的回文子字符串 for (int i = 0; i &lt; s.length(); ++i) { count += extendSubstrings(s, i, i); // 奇数长度子串 count += extendSubstrings(s, i, i + 1); // 偶数长度子串 } return count; } int extendSubstrings(string s, int l, int r) { int count = 0; while (l &gt;= 0 &amp;&amp; r &lt; s.length() &amp;&amp; s[l] == s[r]) { --l; ++r; ++count; } return count; } // Manacher 算法是在线性时间内求解最长回文子串的算法。 // Manacher 算法也会面临「方法一」中的奇数长度和偶数长度的问题， // 它的处理方式是在所有的相邻字符中间插入 #，比如 abaa 会被处理成 #a#b#a#a#， // 这样可以保证所有找到的回文串都是奇数长度的，以任意一个字符为回文中心， // 既可以包含原来的奇数长度的情况，也可以包含原来偶数长度的情况 int countSubstrings(string s) { int n = s.size(); string t = &#34;$#&#34;; for (const char &amp;c: s) { t += c; t += &#39;#&#39;; } n = t.size(); t += &#39;!&#39;; // 以 t 的第 i 位为回文中心，可以拓展出的最大回文半径， // 那么 f(i)−1 就是以 i 为中心的最大回文串长度 auto f = vector &lt;int&gt; (n); int iMax = 0, rMax = 0, ans = 0; for (int i = 1; i &lt; n; ++i) { // 遍历待选的回文中心 // 初始化 f[i] f[i] = (i &lt;= rMax) ? min(rMax - i + 1, f[2 * iMax - i]) : 1; // 中心拓展 while (t[i + f[i]] == t[i - f[i]]) ++f[i]; // 动态维护 iMax 和 rMax if (i + f[i] - 1 &gt; rMax) { iMax = i; rMax = i + f[i] - 1; } // 统计答案, 当前贡献为 (f[i] - 1) / 2 上取整 ans += (f[i] / 2); } return ans; } // 696 01字符串，统计有多少非空01子串的0和1数量相同 int countBinarySubstrings(string s) { // 从左往右遍历数组，记录和当前位置数字相同且连续的长度，以及其之前连续的不同数字的长度 // 将字符串 s 按照 0 和 1 的连续段分组，存在 counts 数组中，例如 s=00111011， // 以得到这样的 counts 数组：counts={2,3,1,2} // 这里 counts 数组中两个相邻的数一定代表的是两种不同的字符。 // 假设 counts 数组中两个相邻的数字为 u 或者 v，它们对应着 u 个 0 和 v 个 1， // 或者 u 个 1 和 v 个 0。它们能组成的满足条件的子串数目为 min{u,v}， // 即一对相邻的数字对答案的贡献。 // 对于某一个位置 i，其实我们只关心 i−1 位置的 counts 值是多少， // 所以可以用一个 last 变量来维护当前位置的前一个位置， // 这样可以省去一个 counts 数组的空间。 int ptr = 0, n = s.size(), last = 0, ans = 0; while (ptr &lt; n) { char c = s[ptr]; int count = 0; while (ptr &lt; n &amp;&amp; s[ptr] == c) { ++ptr; ++count; } ans += min(count, last); last = count; } return ans; } // 227 给定含加减乘除运算的字符串，求结果只保留整数。没有()影响优先级 int calculate(string s) { vector&lt;int&gt; stk; char preSign = &#39;+&#39;; int num = 0; int n = s.length(); for (int i = 0; i &lt; n; ++i) { if (isdigit(s[i])) { num = num * 10 + int(s[i] - &#39;0&#39;); // 左数字 } if (!isdigit(s[i]) &amp;&amp; s[i] != &#39; &#39; || i == n - 1) { // 符号或末端 // 先进行所有乘除运算，并将这些乘除运算后的整数值放回原表达式的相应位置 switch (preSign) { // 加减放入栈中 case &#39;+&#39;: stk.push_back(num); break; case &#39;-&#39;: stk.push_back(-num); break; // 乘除直接进行运算 case &#39;*&#39;: stk.back() *= num; break; default: stk.back() /= num; } preSign = s[i]; num = 0; } } return accumulate(stk.begin(), stk.end(), 0); } KMP算法 // 28 字符串匹配 // 判断一个字符串是不是另一字符串的子字符串，是则返回其位置 // KMP算法 O(m+n)通过动规完成匹配 // 当出现不匹配时，找到不匹配字符之前的后缀，找到与这个后缀相同的前缀的后边开始继续匹配 // 如aabaaf，在f处不匹配，则找到f前有 最长的相同后缀(aa45)与前缀(aa12) // 跳到前缀(aa12)的后一个字符b处开始继续匹配 // 在有前缀表后可以快速查询，在不匹配字符前的匹配子串的最长相等前后缀的长度 // aabaaf的前缀表是{0,1,0,1,2,0} // 当在f处不匹配，其之前匹配字符aabaa的最长相等前后缀长为2.则直接跳到index=2处的b开始继续匹配 // O(m*n)的暴力匹配中。当needle(pattern)的某个字符不匹配时需要重新跳回needle的第一个字符重新开始匹配 // KMP解决的就是跳回重新头重新匹配浪费的问题。 // 可以将匹配过程理解为将needle(模式串)在haystack上滑动匹配的过程。 // 当needle出现不匹配时，直接将needle移动到haystack上下个已知的与needle前缀相同的位置上。 // 跳过重新对needle前缀的匹配。 // 这个needle前缀就是当前已完成匹配的needle[0:i]的最长的相等的真前缀与真后缀的长度对应的needle前缀 int strStr(string haystack, string needle) { int n = haystack.size(), m = needle.size(); if (m == 0) { return 0; } vector&lt;int&gt; pi(m,0); // 模式串前缀表 // pi[i] -- needle的子串needle[0:i]最长的相等的真前缀与真后缀的长度。 // 特别地，如果不存在符合条件的前后缀，那么 pi[i]=0。 // 其中真前缀与真后缀的定义为不等于自身的的前缀与后缀 // 我们举个例子说明：字符串 aabaaab 的前缀函数值依次为 0,1,0,1,2,2,3。 // π(0)=0，因为 a 没有真前缀和真后缀，根据规定为 0（可以发现对于任意字符串 π(0)=0 必定成立）； // π(1)=1，因为 aa 最长的一对相等的真前后缀为 a，长度为 1； // π(2)=0，因为 aab 没有对应真前缀和真后缀，根据规定为 0； // π(3)=1，因为 aaba 最长的一对相等的真前后缀为 a，长度为 1； // π(4)=2，因为 aabaa 最长的一对相等的真前后缀为 aa，长度为 2； // π(5)=2，因为 aabaaa 最长的一对相等的真前后缀为 aa，长度为 2； // π(6)=3，因为 aabaaab 最长的一对相等的真前后缀为 aab，长度为 3。 for (int i = 1, j = 0; i &lt; m; i++) { while (j &gt; 0 &amp;&amp; needle[i] != needle[j]) { j = pi[j - 1]; // 如果下一位不同，往前回溯 } if (needle[i] == needle[j]) { j++; // 如果下一位相同，更新相同的最大前缀和最大后缀长 } pi[i] = j; } for (int i = 0, j = 0; i &lt; n; i++) { while (j &gt; 0 &amp;&amp; haystack[i] != needle[j]) { j = pi[j - 1]; // 有部分匹配，往前回溯 } if (haystack[i] == needle[j]) { j++; } if (j == m) { return i - m + 1; // 说明j移动到needle的最末端，返回相应的位置 } } return -1; } 单调栈 // 单调栈模板（单调递减栈） // 栈内元素始终保持单调递增或递减。常用于解决 下一个更大元素、下一个更小元素 等问题。 vector&lt;int&gt; nextGreaterElement(const vector&lt;int&gt;&amp; nums) { int n = nums.size(); vector&lt;int&gt; res(n, -1); // 默认值为-1 stack&lt;int&gt; stk; // 单调递减栈 for (int i = 0; i &lt; n; ++i) { // 当栈不为空且当前元素大于栈顶元素时 while (!stk.empty() &amp;&amp; nums[i] &gt; nums[stk.top()]) { res[stk.top()] = nums[i]; // 更新栈顶元素的下一个更大元素 stk.pop(); // 弹出栈顶元素 } stk.push(i); // 当前元素入栈 } return res; } // 给定每日温度数组 T，返回到下个比当前高温日子需要等大的天数。 vector&lt;int&gt; dailyTemperatures(const vector&lt;int&gt;&amp; T) { int n = T.size(); vector&lt;int&gt; res(n, 0); stack&lt;int&gt; stk; for (int i = 0; i &lt; n; ++i) { while (!stk.empty() &amp;&amp; T[i] &gt; T[stk.top()]) { int prevIdx = stk.top(); res[prevIdx] = i - prevIdx; // 计算天数差 stk.pop(); } stk.push(i); } return res; } int main() { vector&lt;int&gt; T = {73, 74, 75, 71, 69, 72, 76, 73}; vector&lt;int&gt; res = dailyTemperatures(T); // 输出: [1, 1, 4, 2, 1, 1, 0, 0] for (int num : res) cout &lt;&lt; num &lt;&lt; &#34; &#34;; return 0; } 堆 完全二叉树，用vector存对这棵树的中序遍历
#include &lt;vector&gt; #include &lt;algorithm&gt; #include &lt;stdexcept&gt; class MaxHeap { private: vector&lt;int&gt; heap; // 上浮操作（插入时使用） void siftUp(size_t idx) { while (idx &gt; 0) { size_t parentIdx = (idx - 1) / 2; if (heap[idx] &lt;= heap[parentIdx]) break; // 满足大顶堆条件 swap(heap[idx], heap[parentIdx]); idx = parentIdx; } } // 下沉操作（删除堆顶时使用） void siftDown(size_t idx) { size_t n = heap.size(); while (true) { size_t leftChild = 2 * idx + 1; size_t rightChild = 2 * idx + 2; size_t largest = idx; // 找到当前节点、左子节点、右子节点中的最大值 if (leftChild &lt; n &amp;&amp; heap[leftChild] &gt; heap[largest]) { largest = leftChild; } if (rightChild &lt; n &amp;&amp; heap[rightChild] &gt; heap[largest]) { largest = rightChild; } // 如果当前节点已经是最大值，则停止下沉 if (largest == idx) break; swap(heap[idx], heap[largest]); idx = largest; } } public: // 插入元素 void push(int val) { heap.push_back(val); // 添加到末尾 siftUp(heap.size() - 1); // 上浮调整 } // 删除堆顶元素 void pop() { if (heap.empty()) throw out_of_range(&#34;Heap is empty&#34;); heap[0] = heap.back(); // 用末尾元素替换堆顶 heap.pop_back(); // 移除末尾元素 if (!heap.empty()) siftDown(0); // 下沉调整 } // 查看堆顶元素 int top() const { if (heap.empty()) throw out_of_range(&#34;Heap is empty&#34;); return heap[0]; } // 判断堆是否为空 bool empty() const { return heap.empty(); } // 返回堆的大小 size_t size() const { return heap.size(); } }; 哈希表简单实现 template &lt;typename T&gt; class HashTable { private: vector&lt;list&lt;T&gt;&gt; hash_table; // 哈希函数 int myhash(const T &amp; obj) const { return hash(obj, hash_table.size()); } public: // size最好是质数 HashTable(int size=31) { hash_table.reserve(size); hash_table.resize(size); } ~HashTable() {} // 查找哈希表是否存在该值 bool contains(const T &amp; obj) { int hash_value = myhash(obj); const list&lt;T&gt; &amp; slot = hash_table[hash_value]; std::list&lt;T&gt;::const_iterator it = slot.cbegin(); for (; it != slot.cend() &amp;&amp; *it != obj; ++it); return it != slot.cend(); } // 插入值 bool insert(const T &amp; obj) { if (contains(obj)) { return false; } int hash_value = myhash(obj); std::list&lt;T&gt; &amp; slot = hash_table[hash_value]; slot.push_front(obj); return true; } // 删除值 bool remove(const T &amp; obj) { list&lt;T&gt; &amp; slot = hash_table[myhash(obj)]; auto it = find(slot.begin(), slot.end(), obj); if (it == slot.end()) { return false; } slot.erase(it); return true; } }; // 一个简单的对整数实现的哈希函数 int hash(const int &amp; key, const int &amp;tableSize) { return key % tableSize; }

UDP通信实现
通信前无三次握手建立连接不需要创建监听套接字直接创建通信的套接字。
send/recv用于tcp sendto/recvfrom用于udp
#include &lt;sys/types.h&gt; #include &lt;sys/socket.h&gt; ssize_t sendto(int sockfd,const void*buf,size_t len,int flags,const struct sockaddr* dest_addr,socklen_t* addrlen); //sockfd UDP通信的fd //buf 要发送的数据 //len 要发送的数据长度 //flags 一些配置去看man 可以直接给0 //dest_addr 目的地址 sockaddr类型填端口号+IP地址 //addrlen dest_addr的大小(和recvfrom不一样 那个是要求指针) //成功返回发送的字节数量失败返回-1 ssize_t recvfrom(int sockfd,const void*buf,size_t len,int flags,struct sockaddr* src_addr,socklen_t *addrlen); //sockfd UDP通信的fd //buf 接收数据的buffer //len 接收buffer的大小 //flags 一些配置去看man 可以直接给0 //src_addr 从哪接收 sockaddr类型 是传出参数 可以通过这个参数看到是哪个客户端给我发消息 //addrlen src_addr大小的指针 src_addr为NULL 这个长度也要为NULL //成功返回接收的字节数量失败返回-1 #include &lt;unistd.h&gt; #include &lt;arpa/inet.h&gt; #include &lt;string.h&gt; #include &lt;sys/types.h&gt; int main() { //1创建UDP socket int cfd = socket(PF_INET, SOCK_DGRAM, 0); //udp SOCK_DGRAM tcp SOCK_STREAM //2 绑定 struct sockaddr_in saddr; saddr.sin_port = htons(9999); saddr.sin_family = AF_INET; saddr.sin_addr.s_addr = INADDR_ANY; //服务器要绑定的地址 服务器任一网卡的ip int ret = bind(cfd, (struct sockaddr *)&amp;saddr, sizeof(saddr)); if (ret == -1) { perror(&#34;bind:&#34;); exit(-1); } //3 通信 while (1) { char recvbuf[128]; struct sockaddr_in client_addr; int len = sizeof(client_addr); int recv_num = recvfrom(cfd, recvbuf, sizeof(recvbuf), 0, (struct sockaddr *)&amp;client_addr, &amp;len); //client_addr是传出参数 将传出是从哪个客户端收到数据 if (recv_num == -1) //出错 { perror(&#34;recvfrom:&#34;); exit(-1); } else { char ipbuf[16]; //传出参数 将转换后的字符串传出 inet_ntop的返回值也是这个传出参数 printf(&#34;server recv from ip:%s port:%d %d bytes\n&#34;, inet_ntop(AF_INET, &amp;client_addr.sin_addr.s_addr, ipbuf, sizeof(ipbuf)), ntohs(client_addr.sin_port), recv_num); printf(&#34;server recv data:%s&#34;, recvbuf); //发送数据 sendto(cfd, recvbuf, strlen(recvbuf) + 1, 0, (struct sockaddr *)&amp;client_addr, sizeof(client_addr)); //回显 将收到的数据原封不动发回去 } } close(cfd); return 0; } 广播
向子网(同一局域网)中多台计算机发送消息，并且子网中所有的计算机都可以接收到对方发送的消息，之前有讲过IP 为网络IP段+主机IP段 当主机IP段全为1则是此子网内的广播IP。
完成广播服务器和客户端需要规定统一的广播端口
**服务器向机IP段全为1的IP地址 的 广播端口发数据 **
注意客户端需要绑定广播端口才能接收到广播数据
服务器设置广播属性客户端绑定广播端口
服务器设置广播属性 int setsockopt(int sockfd,int level,int optname,const void* optval,socklen_t optlen);
sockfd 套接字文件描述符
level 指定系统中解释选项的代码或为通用套接字代码，或为某个特定于协议的代码(如IPV4,IPV6,TCP) 可选参数 SOL_SOCKET IPPROTO_IP IPPROTO_IPV6 IPPROTO_TCP&hellip;
lecvel和optname是一起使用的 在某个level下某个optname有&hellip;的设置作用。参数太多看具体的可以看上面讲的那本书，下面这张图只是其中一部分
