消费者
容器无内容后不再消费阻塞 并通知生产者去生产
/* 生产者消费者模型 也叫有限缓冲模型 生产者向容器中添加节点 消费者从容器中删除节点 条件变量 不是锁 但是可以在某个条件满足后阻塞线程或解阻塞线程 pthread_cond_t int pthread_cond_init(pthread_cond_t *restrict cond, pthread_condattr_t *restrict cond_attr); 初始化条件变量 int pthread_cond_destroy(pthread_cond_t *cond); 销毁条件变量 int pthread_cond_wait(pthread_cond_t *restrict cond, pthread_mutex_t *restrict mutex); 阻塞函数 等待被唤醒(在信号或广播唤醒前一直等待) pthread_cond_wait的线程在等待期间会将锁给让出去 当前线程在等待时是不拿锁的 在被唤醒等待结束不阻塞时 锁又会还给这个在等待的线程 int pthread_cond_timedwait(pthread_cond_t *restrict cond, pthread_mutex_t *restrict mutex, const struct timespec *restrict abstime); 阻塞函数 等待被唤醒(在信号或广播唤醒或阻塞的实际还没有超过设定的abstime前 一直等待) 等待期间会将锁给让出去 当前线程在等待时是不拿锁的 在被唤醒等待结束不阻塞时 锁又会还给这个在等待的线 int pthread_cond_signal(pthread_cond_t *cond); 唤醒1个或多个在等待的线程 int pthread_cond_broadcast(pthread_cond_t *cond); 唤醒所有在等待的线程 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; #include &lt;stdlib.h&gt; //malloc pthread_rwlock_t rwlock; //全局读写锁量 void *produce(void *arg); void *custom(void *arg); //使用链表作为容器 假设这个容器不会满 但是会空 typedef struct Node { int data; struct Node *next; } Node; Node *head = NULL; //头节点 //创建条件变量 pthread_cond_t cond; int main() { //初始化互斥量 pthread_rwlock_init(&amp;rwlock, NULL); //初始化条件变量 pthread_cond_init(&amp;cond, NULL); // 创建3个子线程 主线程只用于管理系统资源 pthread_t ptids[5], ctids[5]; //线程数组 5个生产者 5个消费者 for (int i = 0; i &lt; 5; i++) { int ret = pthread_create(&amp;ptids[i], NULL, produce, NULL); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } //不join了 直接将10个线程都分离 由系统回收 pthread_detach(ptids[i]); } for (int i = 0; i &lt; 5; i++) { int ret = pthread_create(&amp;ctids[i], NULL, custom, NULL); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } //不join了 直接将10个线程都分离 由系统回收 pthread_detach(ctids[i]); } while (1) { sleep(10); break; } pthread_cond_destroy(&amp;cond); //子线程执行10秒后就将锁销毁 pthread_rwlock_destroy(&amp;rwlock); //pthread_exit(NULL); //让主线程退出 当主线程退出时 不会影响其他正常运行的线程 return 0; //不会执行 } // 这整个链表就像栈 生产和消费的过程就是出栈和入栈 生产出来加在队首 消费也优先消费队首的节点 // 生产和消费都是写操作 void *produce(void *arg) //生产线程 向容器添加内容 不断创建节点添加到链表中--新节点直接作为新的头节点 { while (1) { pthread_rwlock_wrlock(&amp;rwlock); Node *new_node = (Node *)malloc(sizeof(Node)); new_node-&gt;data = rand() % 1000; new_node-&gt;next = head; head = new_node; printf(&#34;%ld produce node %d\n &#34;, pthread_self(), new_node-&gt;data); //只要生产了一个就通知消费者消费 唤醒在等待的消费者 pthread_cond_signal(&amp;cond); pthread_rwlock_unlock(&amp;rwlock); usleep(1000); //每个线程在产生一个新节点后至少1ms不生产新节点 } return NULL; } void *custom(void *arg) { while (1) { pthread_rwlock_wrlock(&amp;rwlock); if (head == NULL) { //1head此时为null说明生产线程还没有生产节点 容器为空 需要将锁给生产线程，让生产线程先生产节点先 // pthread_rwlock_unlock(&amp;rwlock); // usleep(1000); //每个线程在消费一个节点后至少1ms不争夺锁 // continue; //2 没有数据阻塞等待 当生产者生产了一个节点会发信号通知 这里就会解除阻塞 pthread_cond_wait(&amp;cond, &amp;rwlock); //当前消费者拿着锁在等待 生产者拿不到锁怎么生产？ //并不会这样 pthread_cond_wait在等待期间会将锁给让出去 当前线程在等待时是不拿锁的 //当唤醒后不再等待 锁又归还给当前线程 pthread_rwlock_unlock(&amp;rwlock); continue; } Node *temp = head; head = head-&gt;next; printf(&#34;%ld custom node %d\n &#34;, pthread_self(), temp-&gt;data); free(temp); //释放头节点 pthread_rwlock_unlock(&amp;rwlock); usleep(1000); //每个线程在消费一个节点后至少1ms不消费新节点 } return NULL; } 信号量
相比条件变量使用起来更灵活方便
/* 信号量(信号灯) 与条件变量类似 用于阻塞线程 但一样不是锁 类型 sem_t #include &lt;semaphore.h&gt; int sem_init(sem_t *sem, int pshared, unsigned int value); 初始化信号量 sem 要初始化的信号量 pshared 此信号量用于线程间还是进程间 为0是线程 非0是进程(信号量在共享内存中) 但LinuxThreads仅实现线程间共享，因此所有非0值的pshared输入都将使sem_init()返回-1，且置errno为ENOSYS。 value 信号量中断的值(总共有几个灯) int sem_destroy(sem_t *sem); 销毁信号量 释放资源 释放自己占用的一切资源，被注销的信号量sem要求已没有线程在等待该信号量了，否则返回-1，且置errno为EBUSY。 wait对信号量加锁 int sem_wait(sem_t *sem); 若当前亮着的灯为0个则阻塞直到亮灯不为0个 不为0不会阻塞 将亮着的灯关掉一个(-1) int sem_trywait(sem_t *sem); sem_trywait()为sem_wait()的非阻塞版，如果信号量计数大于0，则信号量立即减1并返回0，否则立即返回-1，errno置为EAGAIN。 int sem_timedwait(sem_t *sem, const struct timespec *abs_timeout); sem_timedwait和sem_wait一样当信号量计数为0会阻塞,但sem_timedwait的abs_timeout参数指定了调用应该阻塞的时间限制 当阻塞超时时返回失败(errno 设置为 ETIMEDOUT) 尽量不要使用sem_timedwait函数来实现延时等待的功能，若要使用该延时等待的功能，建议使用sem_trywait+usleep 实现的延时阻塞 int sem_post(sem_t *sem); 解锁一个信号量(开一个灯(+1)) 唤醒在wait的线程(它获得了一个信号量锁) 它是一个“原子操作”，即同时对同一个信号量做加“1”操作的两个线程是不会冲突的,一个先加1一个后加1最后是加2 int sem_getvalue(sem_t *sem, int *sval); 读取sem中信号量计数，存于*sval中，并返回0。 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; #include &lt;stdlib.h&gt; //malloc #include &lt;semaphore.h&gt; pthread_rwlock_t rwlock; //全局读写锁量 void *produce(void *arg); void *custom(void *arg); //使用链表作为容器 假设这个容器不会满 但是会空 typedef struct Node { int data; struct Node *next; } Node; Node *head = NULL; //头节点 //创建条两个信号量 sem_t csem, psem; int main() { //初始化互斥量 pthread_rwlock_init(&amp;rwlock, NULL); //初始化信号量 //这个10限定了容器中最多只会有10个节点 生产者灭的灯数+消费者亮的灯数=消费者灭的灯数+生产者亮的灯数=10 这个式子永远是恒等的 sem_init(&amp;psem, 0, 10); //生产者的信号量初始值为10 这个值其实可以设置为容器的上限 sem_init(&amp;csem, 0, 0); //消费的信号量初始值为0 这意味着消费者一开始是阻塞的(因为生产者还没生产 容器为空不允许消费) // 创建子线程 主线程只用于管理系统资源 pthread_t ptids[5], ctids[5]; //线程数组 5个生产者 5个消费者 for (int i = 0; i &lt; 5; i++) { int ret = pthread_create(&amp;ptids[i], NULL, produce, NULL); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } //不join了 直接将10个线程都分离 由系统回收 pthread_detach(ptids[i]); } for (int i = 0; i &lt; 5; i++) { int ret = pthread_create(&amp;ctids[i], NULL, custom, NULL); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } //不join了 直接将10个线程都分离 由系统回收 pthread_detach(ctids[i]); } while (1) { sleep(10); break; } sem_destroy(&amp;csem); sem_destroy(&amp;psem); //子线程执行10秒后就将锁销毁 pthread_rwlock_destroy(&amp;rwlock); // pthread_exit(NULL); //让主线程退出 当主线程退出时 不会影响其他正常运行的线程 return 0; //不会执行 } // 这整个链表就像栈 生产和消费的过程就是出栈和入栈 生产出来加在队首 消费也优先消费队首的节点 // 生产和消费都是写操作 //生产者灭的灯数+消费者亮的灯数=消费者灭的灯数+生产者亮的灯数=10 这个式子永远是恒等的 void *produce(void *arg) //生产线程 向容器添加内容 不断创建节点添加到链表中--新节点直接作为新的头节点 { while (1) { sem_wait(&amp;psem); //每生产一次 生产者亮灯数减1 当亮灯数为0 阻塞等待消费者消费 pthread_rwlock_wrlock(&amp;rwlock); Node *new_node = (Node *)malloc(sizeof(Node)); new_node-&gt;data = rand() % 1000; new_node-&gt;next = head; head = new_node; printf(&#34;%ld produce node %d\n&#34;, pthread_self(), new_node-&gt;data); //只要生产了一个就通知消费者消费 唤醒在等待的消费者 pthread_rwlock_unlock(&amp;rwlock); sem_post(&amp;csem); //已经生产了一个节点消费者亮灯数+1 并唤醒消费者线程中在wait的线程去消费 usleep(1000); //每个线程在产生一个新节点后至少1ms不生产新节点 } return NULL; } void *custom(void *arg) { while (1) { //消费者不再需要单独地判断容器是否为空 //当容器为空 则消费者亮灯数为0 自然阻塞 等待生产者生产将消费者灯点亮 sem_wait(&amp;csem); pthread_rwlock_wrlock(&amp;rwlock); Node *temp = head; head = head-&gt;next; printf(&#34;%ld custom node %d\n&#34;, pthread_self(), temp-&gt;data); free(temp); //释放头节点 pthread_rwlock_unlock(&amp;rwlock); sem_post(&amp;psem); //已经消费了一个节点灭了一个消费者灯 需要量一个生产者灯 并唤醒生产者线程中在wait的线程去生产 usleep(1000); //每个线程在消费一个节点后至少1ms不消费新节点 } return NULL; }

线程概述
与进程(process)类似，线程(thread)是允许应用程序并发执行多个任务的一种机制。
一个进程可以包含多个线程。同一个程序中的所有线程均会独立执行相同的程序，且共享同一份全局内存区域，其中包括初始化数据段、未初始化数据段，以及堆内存段。
(传统意义上的unix进程只是多线程的一个特例 该进程只包含一个线程)
进程是cpu分配资源的最小单位，线程是OS调度执行的最小单位。
线程是轻量级的进程LWP(light weight process)在linux环境下线程的本质仍是进程。
查看指定进程的LWP号 ps -Lf 指定进程的pid (PID都一样 但每个线程都有自己的LWP号)
为什么有了进程后还有有线程
进程间的信息难以共享。对于父子进程来说除去只读代码区外，父子进程并未共享内存，因此必须采用一些进程间通信方式，在进程间进行信息交换。
调用fork()来创建进程的代价相对较高，即使利用写时拷贝技术，仍需要复制诸如内存页表和文件描述符表之类的多种进程属性，这意味着fork()调用在时间上的开销依然不菲。
线程之间能够方便、快速地共享信息。只需将数据复制到共享(全局或堆malloc)变量中即可。
创建线程比创建进程通常要快10倍甚至更多。线程间是共享虚拟地址空间的，无需采用写时拷贝来复制内存也无需复制页表。
所有线程共用同一块虚拟地址空间，但是会给不同线程划分栈空间和.text代码段的空间(将栈空间和.text分成小块分给这些线程)，main线程(主线程)的栈、线程1的栈&hellip; main线程的代码，线程1的代码&hellip;，其他部分都是共享相同的。
线程间共享的资源
进程PID 父进程ID PPID
进程组ID 会话ID
用户ID 用户组ID
文件描述符表
信号处置 (信号处理)
文件系统相关信息：文件权限掩码(mask)、当前工作目录
虚拟地址空间(除栈和.text段)
非共享资源
线程ID
信号掩码 (阻塞信号集)
线程特有数据
error变量
实时调度策略和优先级
栈、本地变量和函数的调用链接信息
查看当前pthread库(NPTL)版本 getconf GNU_LIBPTHREAD_VERSION
创建线程
man pthread_加tab可以查看基本上所有线程相关的函数
#include &lt;pthread.h&gt;
int pthread_create(pthread_t *thread, const pthread_attr_t *attr,
void *(*start_routine) (void *), void *arg);
pthread_t pthread_self(void);
int pthread_equal(pthread_t t1, pthread_t t2);
void pthread_exit(void *retval);
int pthread_join(pthread_t thread, void **retval);
int pthread_detach(pthread_t thread);
int pthread_cancel(pthread_t thread);
/* #include &lt;pthread.h&gt; int pthread_create(pthread_t *thread, const pthread_attr_t *attr, void *(*start_routine) (void *), void *arg); 创建一个子线程(main为主线程) thread 传出参数，当子线程创建成功后线程id会由这个指针传出 attr 设置的线程属性 使用默认值 传入null start_routine 子线程所要处理的代码的函数的指针 arg 为start_routine传参 返回值 成功返回0 失败返回错误号(man3中查看) 这个错误号和之前errno不太一样 不能通过perror输出 获取出错误号的信息 在string.h中char* strerror(int errnum)来获得这个错误号对应的错误信息 注意线程pthread库并非linux gcc自带库 libpthread.so 在编译时需要指定-pthread gcc learn_pthread_create.c -0 create -pthread gcc learn_pthread_create.c -0 create -l pthread 都对 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void *callback(void *arg); int main() { // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, NULL, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } sleep(1); //防止主线程结束了 子线程的callback还没执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); return NULL; } 终止线程
/* #include &lt;pthread.h&gt; void pthread_exit(void *retval); 终止一个线程 在哪个线程中调用 就是终止哪个线程 retval 传出参数 可被pthread_join函数获取该线程的返回值 pthread_t pthread_self(void) 获取当前线程的线程ID int pthread_equal(pthread_t t1, pthread_t t2); 判断t1与t2的线程号是否相等 为什么不用==判断呢 因为不同OS pthread_t类型的实现不一样 有的是无符号长整型(当前Linux系统中是这种类型) 有的是结构体实现的 结构体就不能==了 注意线程pthread库并非linux gcc自带库 libpthread.so 在编译时需要指定-pthread gcc learn_pthread_create.c -0 create -pthread gcc learn_pthread_create.c -0 create -l pthread 都对 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void *callback(void *arg); int main() { // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, NULL, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } pthread_exit(NULL); //让子线程退出 当主线程退出时 不会影响其他正常运行的线程 //主线程结束 pthread_exit下面的代码是不会执行的 即不会打印main thread exsit printf(&#34;main thread exsit\n&#34;); //不会执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; //不会执行 // 主线程、子线程调用exit， pthread_exit，互相产生的影响。 // 1、在主线程中，在main函数中return了或是调用了exit函数，则主线程退出，且整个进程也会终止， // 此时进程中的所有线程也将终止。因此要避免main函数过早结束。 // 2、在主线程中调用pthread_exit, 则仅仅是主线程结束，进程不会结束，进程内的其他线程也不会结束， // 直到所有线程结束，进程才会终止。 // 3、在任何一个线程中调用exit函数都会导致进程结束。进程一旦结束，那么进程中的所有线程都将结束。 /** * 1: 线程使用return (这种方法对线程还适用，从main函数return 相当于调用exit 但是在子线程中return 相当于调用pthread_exit 除了最后一个子线程return 那也相当于exit) * 2: 调用pthread_cancel (一个线程可以调用pthread_cancel终止同一进程中的另一个线程) * 3: 调用pthread_exit(线程可以调用pthread_exit终止自己,有两种情况需要注意： * 一种情况是，在主线程中，如果从main函数返回或是调用了exit函数退出主线程， * 则整个进程将终止，此时进程中有线程也将终止，因此在主线程中不能过早地从main * 函数返回； * 另外一种情况：如果主线程调用pthread_exit函数，则仅仅是主线程消亡， * 进程不会结束，进程内的其他子线程也不会终止，直到所有线程结束，进程才会结束； * 线程终止最重要的问题是资源释放问题，特别是一些临界资源在一段时间内只能被 * 一个线程所持有，当线程要使用临界资源需提出请求，如果该资源未被使用则申请 * 成功，否则等待。临界资源使用完毕后要释放以便其它线程可以使用。 **/ } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); pthread_t id = pthread_self(); printf(&#34;id: %ld\n&#34;, id); return NULL; //相当于pthread_exit(NULL) } 连接已终止的线程
/* #include &lt;pthread.h&gt; int pthread_join(pthread_t thread, void **retval); 连接已经终止的线程 回收子线程的资源 此函数阻塞 没有线程结束这个函数一直阻塞 直到有线程结束此函数回收后才能运行下面的语句 调用一次只能回收一个线程 一般在主线程中使用 参数 thread需要回收的线程ID retval 接收子线程退出时的返回值 二级指针 线程结束时(通过pthread_exit退出传入返回值)这个返回值可被retval得到 返回值 成功返回0 失败返回错误号(man3中查看) 这个错误号和之前errno不太一样 不能通过perror输出 获取出错误号的信息 在string.h中char* strerror(int errnum)来获得这个错误号对应的错误信息 类比进程，子进程结束父进程有责任wait or waitpid去回收子进程的PCB资源 如果不回收子进程将变为僵尸进程 子线程结束后不会收将会产生僵尸线程 子线程不需要一定要主线程(main线程)去回收 任何线程都可以去回收其他已经结束的线程 注意线程pthread库并非linux gcc自带库 libpthread.so 在编译时需要指定-pthread gcc learn_pthread_create.c -0 create -pthread gcc learn_pthread_create.c -0 create -l pthread 都对 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void *callback(void *arg); int main() { // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, NULL, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } int *t_return; //返回值是二级指针 是因为callback的返回值类型被规定为一级指针void* pthread_join(tid, (void **)&amp;t_return); //阻塞回收子线程资源 //子线程的返回值保存在 t_return中 printf(&#34;son thread return %d\n&#34;, *t_return); pthread_exit(NULL); //让子线程退出 当主线程退出时 不会影响其他正常运行的线程 //主线程结束 pthread_exit下面的代码是不会执行的 即不会打印main thread exsit printf(&#34;main thread exsit\n&#34;); //不会执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; //不会执行 } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); pthread_t id = pthread_self(); printf(&#34;id: %ld\n&#34;, id); // int val = 100; //局部变量 返回的还是这个变量的地址 //主线程拿去的时候这个变量已经销毁了(子线程栈释放了) 主线程得到的是野内存随机值 static int val = 100; //全局存储区 //通过pthread_exit结束子进程 并返回值 pthread_exit((void *)&amp;val); //与return (void *)&amp;val是一样的!!!!!! 返回一个局部变量是没有意义的 // return NULL; //相当于pthread_exit(NULL) } 线程的分离
/* #include &lt;pthread.h&gt; int pthread_detach(pthread_t thread); 标记传入的线程thread为detach分离状态 当分离状态的线程终止 其资源会自动释放还给系统 不再需要其他线程join来回收此线程的资源！！！！ 当去分离一个已经是分离状态的线程将会导致位未知的结果 不能去连接(join)一个已经分离(detach)的线程 成功返回0 失败返回strerror的错误号 注意线程pthread库并非linux gcc自带库 libpthread.so 在编译时需要指定-pthread gcc learn_pthread_create.c -0 create -pthread gcc learn_pthread_create.c -0 create -l pthread 都对 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void * callback(void *arg); int main() { // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, NULL, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } pthread_detach(tid); //设置子线程分离 当分离状态的线程终止 其资源会自动释放还给系统 不再需要其他线程join来回收此线程的资源！！！！ pthread_exit(NULL); //让子线程退出 当主线程退出时 不会影响其他正常运行的线程 //主线程结束 pthread_exit下面的代码是不会执行的 即不会打印main thread exsit printf(&#34;main thread exsit\n&#34;); //不会执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; //不会执行 } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); pthread_t id = pthread_self(); printf(&#34;id: %ld\n&#34;, id); // int val = 100; //局部变量 返回的还是这个变量的地址 //主线程拿去的时候这个变量已经销毁了(子线程栈释放了) 主线程得到的是野内存随机值 static int val = 100; //全局存储区 //通过pthread_exit结束子进程 并返回值 pthread_exit((void *)&amp;val); //与return (void *)&amp;val是一样的!!!!!! 返回一个局部变量是没有意义的 // return NULL; //相当于pthread_exit(NULL) } 线程取消
/* #include &lt;pthread.h&gt; int pthread_cancel(pthread_t thread); 给传入的thread号线程发送取消请求(终止线程) 对应线程是否以及合适终止 取决于对应线程的两个参数 他的cancelabilityd的state以及type 在pthread_create创建线程的第二个参数可以传入一个结构体来设置这两个属性 系统并不能保证在调用pthread_cancel后立即取消线程 只有当线程运行到cancellation point取消点函数 线程会才会取消！！！！！！！ 取消点函数可以在man pthreads中查看有很多 一般是系统调用 所以我们可以粗略地人为一般的系统调用是取消点函数 如果子线程中没有取消点的话，子线程会一直运行到结束(return or pthread_exit) 或者可以通过 pthread_setcanceltype 成功返回0 失败返回strerror的错误号 注意线程pthread库并非linux gcc自带库 libpthread.so 在编译时需要指定-pthread gcc learn_pthread_create.c -0 create -pthread gcc learn_pthread_create.c -0 create -l pthread 都对 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void * callback(void *arg); int main() { // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, NULL, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } //取消子线程 pthread_cancel(tid); //子线程中的printf是取消点 for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } pthread_exit(NULL); //让子线程退出 当主线程退出时 不会影响其他正常运行的线程 //主线程结束 pthread_exit下面的代码是不会执行的 即不会打印main thread exsit printf(&#34;main thread exsit\n&#34;); //不会执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; //不会执行 } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); pthread_t id = pthread_self(); printf(&#34;id: %ld\n&#34;, id); // int val = 100; //局部变量 返回的还是这个变量的地址 //主线程拿去的时候这个变量已经销毁了(子线程栈释放了) 主线程得到的是野内存随机值 static int val = 100; //全局存储区 //通过pthread_exit结束子进程 并返回值 pthread_exit((void *)&amp;val); //与return (void *)&amp;val是一样的!!!!!! 返回一个局部变量是没有意义的 // return NULL; //相当于pthread_exit(NULL) } 线程属性
