/* int pthread_attr_init(pthread_attr_t* attr); 初始化线程属性变量 线程属性不止一些标志位还有一些复杂的变量 所以在pthread_attr_t创建出来后 不能简单地 显式地设置一些属性 需要调用init函数来将这个变量清空 int pthread_attr_destroy(pthread_attr_t* attr); 释放线程属性的资源 int pthread_attr_getdetachstate(const pthread_attr_t* attr,int *detachstate); 获取线程分离状态的属性 detachstate为传出参数 创建线程时可以直接指定线程是detached状态还是joinable状态(其实就是不分离的状态) PTHREAD_CREATE_DETACHED 线程结束后不需要其他线程去join回收资源 系统会回收这个线程的资源 PTHREAD_CREATE_JOINABLE(默认的线程的状态) int pthread_attr_setdetachstate(pthread_attr_t* attr,int *detachstate); 设置线程分离状态的属性 int pthread_attr_getstacksize(const pthread_attr_t* attr,size_t *stacksize); stacksize为传出参数是线程栈的大小 \*/ #include &lt;stdio.h&gt; #include &lt;pthread.h&gt; #include &lt;string.h&gt; #include &lt;unistd.h&gt; void * callback(void *arg); int main() { //创建线程属性变量 pthread_attr_t attr; //线程属性不止一些标志位还有一些复杂的变量 所以在pthread_attr_t创建出来后 //不能简单地 显式地设置一些属性 需要调用init函数来将这个变量清空 pthread_attr_init(&amp;attr); //设置线程创建后的分离状态的属性 pthread_attr_setdetachstate(&amp;attr, PTHREAD_CREATE_DETACHED); //使用attr创建后就是分离状态 //获取线程栈的大小(因为我们没有设置过线程栈的大小 所以这里获取到的是线程栈的默认大小) size_t *size; pthread_attr_getstacksize(&amp;attr, &amp;size); printf(&#34;thread default stacksize is %ld\n&#34;, size); //8388608B = 8MB 默认线程栈大小为8MB // 创建一个子线程 pthread_t tid; int num = 10; //可以搞个结构体将函数的参数全部放在那个结构体里 再往回调函数内传 int ret = pthread_create(&amp;tid, &amp;attr, callback, (void *)&amp;num); if (ret != 0) { printf(&#34;%s\n&#34;, strerror(ret)); } for (int i = 0; i &lt; 5; i++) { printf(&#34;parent thread\n&#34;); } //释放子线程属性资源 pthread_attr_destroy(&amp;attr); pthread_exit(NULL); //让子线程退出 当主线程退出时 不会影响其他正常运行的线程 //主线程结束 pthread_exit下面的代码是不会执行的 即不会打印main thread exsit printf(&#34;main thread exsit\n&#34;); //不会执行 //当主线程return 相当于进程exit所有子线程全部结束！！！ return 0; //不会执行 } void *callback(void *arg) { printf(&#34;child thread\n&#34;); printf(&#34;arg value %d\n&#34;, *(int *)arg); pthread_t id = pthread_self(); printf(&#34;id: %ld\n&#34;, id); // int val = 100; //局部变量 返回的还是这个变量的地址 //主线程拿去的时候这个变量已经销毁了(子线程栈释放了) 主线程得到的是野内存随机值 static int val = 100; //全局存储区 //通过pthread_exit结束子进程 并返回值 pthread_exit((void *)&amp;val); //与return (void *)&amp;val是一样的!!!!!! 返回一个局部变量是没有意义的 // return NULL; //相当于pthread_exit(NULL) }

信号
信号是Linux进程间通信的最古老的方式之一，是事件发生时对进程的通知机制，有时也称之为软件中断,它是在软件层次上对中断机制的一种模拟，是一种异步通信的方式。信号可以导致一个正在运行的进程被另一个正在运行的异步进程中断，转而处理某一个突发事件，发往进程的诸多信号，通常都是源于内核。引发内核为进程产生信号的各类事件如下:
对于前台进程(占用shell)，用户可以通过输入特殊的终端字符来给它发送信号。比如Ctrl+C通常会给进程发送一个中断信号。
硬件发生异常，即硬件检查到一个错误条件并通知内核，随即再由内核发送相应信号给相关进程。比如执行一条异常的机器语言指令，诸如被除0，或者引用了无法访问的内存区域。
系统状态变化，比如alarm定时器到期将引起SIGALRM信号，进程执行的cpu时间超限，或者该进程的某个子进程退出。
运行kill命令或调用kill命令
一般信号用于两种用途:1让进程知道已经发生了一个特定的事情2强迫进程执行它自己代码中的信号处理程序
信号的特定：简单，不能携带大量信息，满足某个特定条件才发送，优先级比较高。
