/* #include &lt;signal.h&gt; typedef void (*sighandler_t)(int);//sighandler_t为函数指针类型 指向只有一个int参数 返回值为0的函数 signal在不同的linux版本是不同的 所以最好用sigaction函数来代替！！！！ sighandler_t signal(int signum, sighandler_t handler); 捕获信号后 执行相关处理 SIGKILL SIGSTOP 无法被捕获和忽略 signum 要捕获的信号的编号 用宏值 handler 信号处理函数 handler 可以用宏值SIG_IGN忽略这个信号 SIG_DFL采取这个信号默认的动作(看笔记里的表 有讲每个signal的默认动作) 如果有给这个信号对应的回调函数指针 则(内核自动调用)执行这个函数 返回值 成功 前一次的handler值(第一次调用 返回null) 失败 返回宏SIG_ERR \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #include &lt;sys/types.h&gt; #include &lt;signal.h&gt; #include &lt;sys/time.h&gt; void sig_handler(int num); int main() { //注册SIGALRM的信号的回调函数 __sighandler_t ret = signal(SIGALRM, sig_handler); //函数名相当于 这个函数的地址 if (ret == SIG_ERR) { perror(&#34;signal:&#34;); return -1; } struct itimerval new_value; new_value.it_interval.tv_sec = 2; //定时器周期时间 new_value.it_interval.tv_usec = 0; //虽然用不到微秒 但还是设置一下 否则是个随机值 负数的话 是tv_sec-|tv_usec| 正数的话是tv_sec+tv_usec new_value.it_value.tv_sec = 3; //过多长时间第一次启动定时器 new_value.it_value.tv_usec = 0; // //过3秒后启动定时器 定时器周期为2秒 setitimer(ITIMER_REAL, &amp;new_value, NULL); //不需要上次的定时器属性 所以old传的是null 非阻塞立即向下执行 while (1) ; //不断地 等待定时器触发回调函数 } void sig_handler(int num) { printf(&#34;捕获到的信号编号为：%d\n&#34;, num); //num=14 SIGALRM } 信号集以及相关函数
信号集许多信号相关的系统调用都需要能表示一组不同的信号，多个信号可以使用一个叫信号集的数据结构来表示，其系统数据类型为sigset_t(64位数据 每一位代表一种信号)。在PCB中有两个非常重要的信号集，一个称之为“阻塞信号集”另一个称之为“未决信号集”。这两个信号集都是内核使用位图(二进制)机制来实现的，但操作系统不允许我们直接对这两个信号集进行位操作，而需要自定义另一个集合，借助信号集操作函数(系统调用)来对PCB的信号集进行修改。阻塞信号集可以修改未决信号集无法修改(只能读)
信号集的“未决”是一种状态指的是从信号的产生到信号被处理前的这一段时间(信号被处理了 就是递达状态)，信号的“阻塞”是一个开关动作，指的是阻止信号被处理，但不是阻止信号产生。
信号的阻塞就是让系统暂时保留信号待以后发送，由于另外有办法让系统忽略信号，所以一般情况下信号的阻塞只是暂时的，只是为了防止信号打断敏感的操作所以暂时阻塞一些信号。
用户通过键盘 ctrl+c 产生2号信号SIGINT(信号被创建)，此时SIGINT还未被处理属于未决状态，**未决信号集存储已经被创建但是没有被处理的信号，此时2-SIGINT位置被置为1（未决信号集中0表示非未决状态 1表示未决状态）。**在未决信号被处理前需要和阻塞信号集进行比较，若此时阻塞信号集的2号位置为0表示2号信号不阻塞(2号信号可被发送)，进程接收到并处理结束后未决信号集的2号位置立即变为0。若此时阻塞信号集的2号位置为1表示2号信号阻塞，则2号信号被阻塞内核暂时不会发送2号信号给线程(直到阻塞信号集中 2号位置为0 内核才会发送这个信号)。 阻塞信号集默认全不阻塞(全0)
信号集相关函数
int sigemptyset(sigset_t *set);
int sigfillset(sigset_t *set);
int sigaddset(sigset_t *set,int signum);
int sigdelset(sigset_t *set,int signum);
int sigismember(const sigset_t *set,int signum);
/* 一下信号集函数都是对自定义的信号集 进行操作！！！！！！！ int sigemptyset(sigset_t *set); 清空信号集中的数据(64位数全置为0) sigset_t相当于一个64位数 传入后将这个六十四位数清0，当这个函数结束后再查看传入的set已经清0了 成功返回0 失败返回-1 int sigfillset(sigset_t *set); 将信号集中所有的标志位置为1(64位数全置为1) 成功返回0 失败返回-1 int sigaddset(sigset_t *set,int signum); 设置信号集set中的signum号信号对应的位置 设为1(用于阻塞某个信号) 设置过后的set会通过set参数传出 成功返回0 失败返回-1 int sigdelset(sigset_t *set,int signum); 设置信号集set中的signum号信号对应的位置 设为0 (不阻塞某个信号) 设置过后的set会通过set参数传出 成功返回0 失败返回-1 int sigismember(const sigset_t *set,int signum); 判断set中signum号信号是否为1(是否阻塞) signum号信号为1 返回1(被阻塞) 为0 返回0(不被阻塞) 失败返回-1 \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #include &lt;sys/types.h&gt; #include &lt;signal.h&gt; //信号集函数 #include &lt;sys/time.h&gt; int main() { //创建一个信号集 sigset_t set; //创建set 但没有初始化 其内容是随机的 所以需要先清空 sigemptyset(&amp;set); //判断SIGINT 是否被置为1了 int ret = sigismember(&amp;set, SIGINT); if (ret == 0) { printf(&#34;SIGINT不阻塞\n&#34;); } else if (ret == 1) { printf(&#34;SIGINT阻塞\n&#34;); } else { printf(&#34;出错\n&#34;); return -1; } //添加信号到信号集中 sigaddset(&amp;set, SIGINT); sigaddset(&amp;set, SIGQUIT); //从信号集中删除信号 sigdelset(&amp;set, SIGQUIT); int ret = sigismember(&amp;set, SIGQUIT); if (ret == 0) { printf(&#34;SIGQUIT不阻塞\n&#34;); } else if (ret == 1) { printf(&#34;SIGQUIT阻塞\n&#34;); } else { printf(&#34;出错\n&#34;); return -1; } return 0; }

sigprocmask函数使用
sigprocmask用于修改内核的信号集 将自定义信号集设置到内核的信号集中，内核未决信号集无法修改(只能获取 通过sigpending)即这个函数用于修改阻塞信号集
int sigprocmask(int how,const sigset_t *set,sigset_t *oldset);
int sigpending(sigset_t *set);
/* 每个进程都有自己的PCB 都有自己的未决信号集和阻塞信号集 int sigprocmask(int how,const sigset_t *set,sigset_t *oldset); 用于将自定义的信号集设置到内核中 how 如何对内核阻塞信号集进行处理 SIG_BLOCK 将用户设置的阻塞信号添加到内核中 即用户的信号集中设置为1的信号 在内核信号集中的对应位置也设置为1 用户信号集设置为0的部分 则内核信号集中对应位置保留不变 内核信号集 mask = mask | set SIG_UNBLOCK 根据set将内核信号集的对应位置解除阻塞 即用户的信号集中设置为1的信号 在内核信号集中的对应位置设置为0(解除阻塞) 用户信号集设置为0的部分 则内核信号集中对应位置保留不变 内核信号集 mask = mask &amp; (~set) SIG_SETMASK 用自定义的信号集 替换内核中PCB的阻塞信号集 set 用户已经初始化好的用户自定义的信号集 oldset 传出参数 保存着上次(这次设置之前)内核中阻塞信号集的值 返回值 成功0 失败-1(有两种错误 分别会设置两种错误号 EFAULT set或oldset指向了此进程虚拟地址外 EINVAL how指定错误) int sigpending(sigset_t *set); 用与获取内核中的 未决信号集 set为传出的未决信号集 返回值 0成功 -1失败 \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #include &lt;sys/types.h&gt; #include &lt;signal.h&gt; //sigprocmask #include &lt;sys/time.h&gt; int main() { //编写一个程序 把所有的常规信号(1-31)的未决状态打印到屏幕 //设置某些信号阻塞再通过键盘产生这些信号 这样的话这些信号状态就是未决的 //设置2、3号信号阻塞 2、3号信号可由键盘直接产生 sigset_t set; sigemptyset(&amp;set); //将2、3号信号添加到信号集中 sigaddset(&amp;set, SIGINT); sigaddset(&amp;set, SIGQUIT); //修改内核中的阻塞信号集为set sigprocmask(SIG_BLOCK, &amp;set, NULL); sigset_t pending_set_now; sigemptyset(&amp;pending_set_now); while (1) { sigpending(&amp;pending_set_now); //遍历输出1-31位未决信号集 for (int i = 0; i &lt;= 31; i++) { if (sigismember(&amp;pending_set_now, i) == 1) //是未决信号 { printf(&#34;1&#34;); } else if (sigismember(&amp;pending_set_now, i) == 0) { printf(&#34;0&#34;); } else { perror(&#34;sigismember:&#34;); return -1; } } printf(&#34;\n&#34;); sleep(1); //解除阻塞 // sigprocmask(SIG_UNBLOCK, &amp;set, NULL); } return 0; } sigaction信号捕捉函数
