/* #include &lt;signal.h&gt; int sigaction(int signum, const struct sigaction *act, struct sigaction *oldact); 检查或改变信号的处理动作(捕获信号 并按我们规定的函数进行回调) signum 要捕捉信号的宏值(编号) act 对这个信号的处理动作 struct sigaction { void (*sa_handler)(int);//void ...(int)函数的指针 指向的是信号回调函数 void (*sa_sigaction)(int, siginfo_t *, void *); sa_sigaction则是另一个信号处理函数，它有三个参数，可以获得关于信号的更详细的信息。当 sa_flags 成员的值 包含了 SA_SIGINFO 标志时，系统将使用 sa_sigaction 函数作为信号处理函数，否则使用 sa_handler 作为信号处理 函数。在某些系统中，成员 sa_handler 与 sa_sigaction 被放在联合体中，因此使用时不要同时设置。 函数指针void ...(int, siginfo_t *, void *) 三个参数分别是sig 捕获的信号的编号，info siginfo_t包含了超详细的信号信息(太长了自己去man2看这个结构体) void * ucontext 指向ucontext_t类型的结构体 sigset_t sa_mask; //信号集类型sigset_t 临时阻塞信号集，在信号回调函数执行期间需要被阻塞的信号集，在回调执行完后就不阻塞了 int sa_flags; 指定信号的处理方式 可以为0表示 用sa_handler来回调处理信号 SA_NOCLDSTOP SA_NOCLDWAIT (since Linux 2.6) SA_NODEFER SA_ONSTACK SA_RESETHAND SA_RESTART SA_RESTORER SA_SIGINFO (since Linux 2.2) 用sa_sigaction来回调处理信号 void (*sa_restorer)(void);//已废弃 指定null }; oldact 上次对这个信号进行的处理动作，传出参数 可不使用传null 成功返回 0 失败返回-1 \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #include &lt;sys/types.h&gt; #include &lt;signal.h&gt; #include &lt;sys/time.h&gt; void sig_handler(int num); int main() { //注册SIGALRM的信号的回调函数 struct sigaction act; act.sa_flags = 0; //表示使用sa_handler来进行函数回调 act.sa_handler = sig_handler; sigaction(SIGALRM, &amp;act, NULL); sigemptyset(&amp;act.sa_mask); //清空临时阻塞信号集表示 不回调时阻塞任何信号 struct itimerval new_value; new_value.it_interval.tv_sec = 2; //定时器周期时间 new_value.it_interval.tv_usec = 0; //虽然用不到微秒 但还是设置一下 否则是个随机值 负数的话 是tv_sec-|tv_usec| 正数的话是tv_sec+tv_usec new_value.it_value.tv_sec = 3; //过多长时间第一次启动定时器 new_value.it_value.tv_usec = 0; // //过3秒后启动定时器 定时器周期为2秒 setitimer(ITIMER_REAL, &amp;new_value, NULL); //不需要上次的定时器属性 所以old传的是null 非阻塞立即向下执行 while (1) ; //不断地 等待定时器触发回调函数 } void sig_handler(int num) { printf(&#34;捕获到的信号编号为：%d\n&#34;, num); //num=14 SIGALRM } 内核实现信号捕捉的过程
