对于同一信号比如SIGALRM信号，在信号被回调捕获后未决信号集中SIGALRM信号对应的位置变为0，此时如果又有SIGALRM信号发出，未决信号集SIGALRM信号对应的位置变为1，如果上次的SIGALRM函数还未执行完成，则这个未决的SIGALRM信号会被阻塞直到上次SIGALRM回调执行完成后，后面的这次SIGALRM信号才有机会被回调函数处理。即在执行某一信号回调时，会自动阻塞同类型的信号。
在回调函数中使用的是临时阻塞信号集sa_mask，在回调函数处理完回到主流程中又切换为内核的阻塞信号集。
常规信号在递达之前产生多次只计一次，而实时信号在递达之前产生多次可以依次放在一个队列里。用户只能获取未决信号集值，无法改变其值。
(1-31)信号集无法记录目前有多少个xxx信号未决或阻塞，只能知道目前有xxx信号未决或阻塞。&mdash;不支持排队 (33-64)支持排队能记录有几个同类型信号未决或阻塞，分别是哪些发出
SIGCHILD信号
SIGCHILD信号产生的条件
子进程终止时
子进程收到SIGSTOP信号 停止时
子进程处在停止态，接受到SIGCONT后唤醒时
以上三种条件都会给父进程发送SIGCHILD信号，父进程默认忽略该信号
可利用SIGCHILD信号解决僵尸进程(子进程结束但父进程没有wait去回收子进程资源 导致子进程变为僵尸进程)的问题。wait是阻塞的所以最好wait不要写在父进程的主流程里，而是写在SIGCHILD信号的回调函数里。
/* 使用SIGCHLD信号解决僵尸进程的问题 \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #include &lt;sys/types.h&gt; #include &lt;signal.h&gt; #include &lt;sys/time.h&gt; #include &lt;sys/wait.h&gt; void sig_handler(int num); int main() { //为了防止 回调函数还没注册成功 就已经有子进程死亡了 先阻塞SIGCHLD信号 sigset_t set; sigemptyset(&amp;set); sigaddset(&amp;set, SIGCHLD); sigprocmask(SIG_BLOCK, &amp;set, NULL); //创建一些子进程 pid_t pid; for (int i = 0; i &lt; 20; i++) //为当前进程创建20个子进程 { pid = fork(); if (pid == 0) //进这里的是子进程 不能再让子进程去创建孙子进程 { break; } else { ; } } if (pid &gt; 0) //父进程 { //捕捉子进程死亡时发送的SIGCHILD信号 //注册SIGCHLD的信号的回调函数 struct sigaction act; act.sa_flags = 0; //表示使用sa_handler来进行函数回调 act.sa_handler = sig_handler; sigaction(SIGCHLD, &amp;act, NULL); sigemptyset(&amp;act.sa_mask); //清空临时阻塞信号集表示 不回调时阻塞任何信号 //注册完回调函数后 解除SG的阻塞 sigprocmask(SIG_UNBLOCK, &amp;set, NULL); while (1) { printf(&#34;parent pid: %d\n&#34;, getpid()); sleep(2); //wait 一次回收一个子进程(阻塞) or waitpid 一次回收一个子进程(可设置非阻塞) //waitpid pid &lt; -1 等待所有子进程的group id = -pid //waitpid pid = -1等待所有子进程 pid = 0 等待所有与当前进程有一样group id的子进程 //waitpid pid &gt; 0 等待多有进程号为指定pid的进程 //waitpid 成功回收返回子进程的pid 若为非阻塞没回收但是还有子进程活着的时候返回0 子进程都死亡返回-1 } } else if (pid == 0) //子进程 { printf(&#34;child pid: %d\n&#34;, getpid()); } } void sig_handler(int num) { printf(&#34;捕获到的信号编号为：%d\n&#34;, num); //num=14 SIGALRM //回收子进程资源 if (num == SIGCHLD) { //wait(NULL); //回收子进程资源 //20个信号这样 并不能完全回收 //当多个信号连续到来会造成后面来的信号被忽略 //在执行相依信号的回调函数体时 那个信号是被阻塞的 //,所以当子进程死亡 发出多个SG信号 SG信号都是未决的 只有第一个信号 //(1-31)信号集无法记录目前有多少个xxx信号未决或阻塞， //只能知道目前有xxx信号未决或阻塞。---不支持排队 // 从开始注册信号到注册成功这段时间里，有n个SIGCHID信号产生的话， // 那么第一个产生的SIGCHID会抢先将未决位置为1，余下的n-1个SIGCHID被丢弃， // 然后当阻塞解除之后，信号处理函数发现这时候对应信号的未决位为1，继而执行函数处理该信号， // 处理函数中的while循环顺带将其他n-1子进程也一网打尽了，在这期间未决位的状态只经历了两次变化，即0-&gt;1-&gt;0 while (1) // 一次信号触发为了防止 有连续的SG信号到来 有的信号没看到 这里用个循环回收连续(很快)死亡的子进程的资源 { //死循环 快速地检查是否有子进程死亡 快速地回收 //回调函数 占用的是父进程的资源 相当于暂时中断 去处理这个信号 处理完回到父进程 //waitpid 和 SIGCHLD 没关系，即使是某个子进程对应的 SIGCHLD 丢失了， //只要父进程在任何一个时刻调用了 waitpid，那么这个进程还是可以被回收的 int ret = waitpid(-1, NULL, WNOHANG); //回收所有子进程资源 不阻塞 一次调用回收一个子进程资源 if (ret &gt; 0) //回收到了一个子进程 printf(&#34;child %d die\n&#34;, ret); else if (ret == 0) //还有子进程 在运行 break; //回到父进程 else if (ret == -1) //无子进程在运行 break; //回到父进程 } } }

有名管道介绍及使用
匿名管道，由于没有名字，只能用于有亲缘关系的进程间通信(通过进程fork 拷贝内核区的文件描述符这个机制来实现)，为了克服这个缺点提出了有名管道(FIFO 先入先出)。
有名管道(FIFO 也是由环形队列实现)不同于匿名管道之处在于它提供路径名与这个管道关联，以FIFO的文件形式存在于文件系统中，并且其打开方式与打开一个普通文件的方式是一样的，这样即使与FIFO的创建进程不存在亲缘关系的进程，只要可以访问该路径就可以彼此通过FIFO互相通信，因此通过FIFO不相关的进程也能交换数据。
一旦打开了FIFO，就能在它上面使用与操作匿名管道和其他文件的系统调用一样的I/O系统调用(如read、write、close)，与管道一样，FIFO也有一个写入端和读取端，并且从管道中读取数据的顺序与写入的顺序是一样的(先入先出)。
FIFO与pipe(匿名管道)的不同点：
1 FIFO在文件中作为一个特殊文件存在，但是FIFO中的内容却存放在内存中(内核中的一个缓存区中)
2 当使用FIFO的进程退出后，FIFO文件将继续保存在文件系统中以便以后使用
3 FIFO有名字，不相关的进程可以通过打开有名管道进行通信
有名管道的使用
通过命令创建有名管道 mkfifo 管道名
通过函数创建有名管道
#include &lt;sys/types.h&gt;
#include &lt;sys/stat.h&gt;
int mkfifo(const char *pathname,mode_t mode);
一旦使用mkfifo创建了一个FIFO就可以用open，常见的文件IO操作含糊书(close read wirte unlink删除)都可以用于FIFO文件
FIFO严格遵顼先入先出，对管道及FIFO的读总是从开始处返回数据(单向队列队首数据)，对它们的写则把数据添加到末尾(向单向队列队尾添加数据)，FIFO文件不支持诸如lseek()等文件定位操作。
一个为只读(写)而打开(open)的管道的进程会阻塞(阻塞在open),直到另一个进程以包含写(读)的方式打开相同的管道，才不会继续阻塞而是继续向下运行。
1 当指向管道写端的fd都close了,此时有进程从管道读端读数据，若此时管道中有剩余数据则读取剩余数据，直到剩余数据被读完后，再次read返回0(读到文件末尾read是返回0的 读出现异常是返回-1的)。
2 有指向管道写端的文件描述符没有关闭(管道写端的引用计数大于0)并且没有进程向管道写端写数据，此时将管道内数据读空后再继续读是出现read阻塞，直到有进程写了一些数据，read读到返回读到的字节数。
3 所有的指向管道读端的文件描述符 都关闭了(管道读端的引用计数为0)，此时有进程向管道中写数据，那么该进程会收到一个信号SIGPIPE，通常这个信号会导致进程异常终止。
4 有指向管道读端的文件描述符没有关闭(管道读端的引用计数大于0)并且没有进程从管道读端读数据，此时有进程向管道中写数据，在管道写满后，再次调用写write会导致写进程阻塞，直到管道中有空位write才不会阻塞并返回写入的字节数。
//为了实验 还需要创建两个进程 我们通过两个.c文件来实现 //这个.c为写fifo进程 #include &lt;stdio.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;stdlib.h&gt; #include &lt;unistd.h&gt; //acess #include &lt;fcntl.h&gt; //open #include &lt;string.h&gt; //strlen int main() { //判断文件是否存在 int ret = access(&#34;f1&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } //打开管道 // 这个进程只向管道里写数据 所以以只写的方式打开管道 int fd = open(&#34;f1&#34;, O_WRONLY); //以只写的形式打开 若没有其他线程以包含读的方式打开文件 这个open会一直阻塞在这!!!! if (fd == -1) { perror(&#34;open:&#34;); return -1; } //写数据 for (int i = 0; i &lt; 100; i++) { char buf[1024]; sprintf(buf, &#34;hello %d\n&#34;, i); //向buf中写数据 printf(&#34;write data:%s\n&#34;, buf); //打印当前buf中的字符数据 write(fd, buf, stelen(buf)); //向管道中写数据 sleep(1); } //当所有读端都关闭 此时有写线程向管道中写数据会收到SIGPIPE信号导致进程直接异常退出 close(fd); //关闭管道 return 0; } //为了实验 还需要创建两个进程 我们通过两个.c文件来实现 //这个.c为读fifo进程 #include &lt;stdio.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;stdlib.h&gt; #include &lt;unistd.h&gt; //acess #include &lt;fcntl.h&gt; //open int main() { //判断文件是否存在 int ret = access(&#34;f1&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } //打开管道 // 这个进程只读管道里的数据 所以以只读的方式打开管道 int fd = open(&#34;f1&#34;, O_RDONLY); //以只读的形式打开 若没有其他线程以包含写的方式打开文件 这个open会一直阻塞在这!!!! if (fd == -1) { perror(&#34;open:&#34;); return -1; } //读数据 while (1) { char buf[1024] = {0}; int len = read(fd, buf, sizeof(buf)); //当写端关闭 并且管道中无数据 返回len=0 if (len == 0) break; printf(&#34;recv buf %s\n&#34;, buf); memset(buf, 0, sizeof(buf)); } close(fd); //关闭管道 return 0; } 有名管道实现简单版聊天功能
A进程先给B发，B收到后再给A发，A收到后。。。就这么交替地进行
一个管道只能单向通信，要实现相互的收发需要用两个管道实现。
进程A 1 以只写方式打开fifo1 以只读的方式打开fifo2 2循环读写数据
while(1){ 获取键盘录入的数据不用scanf(遇到换行就结束)而使用fgets; 并将录入的数据写管道1; 读管道2;
}
进程B 1 以只读方式打开fifo1 以只写的方式打开fifo2 2循环读写数据
while(1){ 读管道1;
获取键盘录入的数据不用scanf(遇到换行就结束)而使用fgets; 并将录入的数据写管道2; }
要实现有名管道的同时读写 需要fork出子进程 父进程open fifo1的读端 进行读
子进程 open fifo2的写端 进行写
A
#include &lt;stdio.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;stdlib.h&gt; #include &lt;unistd.h&gt; //acess #include &lt;fcntl.h&gt; //open #include &lt;string.h&gt; //open int main() { //判断有名管道文件是否存在 //存在则不再创建 不存在则创建 int ret = access(&#34;fifo1&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else //-1 { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } int ret = access(&#34;fifo2&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else //-1 { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } // 以只写的方式打开管道fifo1 int fdw = open(&#34;fifo1&#34;, O_WRONLY); if (fdw == -1) { perror(&#34;open FIFO1 WRITE:&#34;); return -1; } //以只读的方式打开管道fifo2 int fdr = open(&#34;fifo2&#34;, O_RDONLY); if (fdr == -1) { perror(&#34;open FIFO2 READ:&#34;); return -1; } char buf[128]; //循环写读数据 while (1) { //写数据 写fifo1 memset(buf, 0, sizeof(buf)); fgets(buf, sizeof(buf), stdin); //从屏幕的stdin标准输入(标准输入也有缓冲区) 获取128个字节并装到buf里 //将从标准输入得到的数据写到fifo里 int ret = write(fdw, buf, strlen(buf)); if (ret == -1) { perror(&#34;write:&#34;); return -1; } //读数据 读fifo2 memset(buf, 0, sizeof(buf)); int len = read(fdr, buf, strlen(buf)); if (len &lt;= 0) { //读出错 -1 读到末尾(或fifo2的写端已经关闭了 并且管道内容被读完了)返回0 perror(&#34;read:&#34;); return -1; } printf(&#34;buf:%s\n&#34;, buf); } close(fdw); close(fdr); return 0; } B
#include &lt;stdio.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;stdlib.h&gt; #include &lt;unistd.h&gt; //acess #include &lt;fcntl.h&gt; //open #include &lt;string.h&gt; //open int main() { //判断有名管道文件是否存在 //存在则不再创建 不存在则创建 int ret = access(&#34;fifo1&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else //-1 { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } int ret = access(&#34;fifo2&#34;, F_OK); //判断叫这个名字的文件是否存在 if (ret == 0) //return 0 表示管道以存在 { ; } else //-1 { int ret = mkfifo(&#34;f1&#34;, 0664); if (ret == -1) { perror(&#34;mkfifo:&#34;); return -1; } } // 以只读的方式打开管道fifo1 int fdr = open(&#34;fifo1&#34;, O_RDONLY); if (fdr == -1) { perror(&#34;open FIFO1 READ:&#34;); return -1; } //以只写的方式打开管道fifo2 int fdw = open(&#34;fifo1&#34;, O_WRONLY); if (fdw == -1) { perror(&#34;open FIFO2 WRITE:&#34;); return -1; } char buf[128]; //循环读写数据 while (1) { //读数据 读fifo1 memset(buf, 0, sizeof(buf)); int len = read(fdr, buf, strlen(buf)); if (len &lt;= 0) { //读出错 -1 读到末尾(或fifo2的写端已经关闭了 并且管道内容被读完了)返回0 perror(&#34;read:&#34;); return -1; } printf(&#34;buf:%s\n&#34;, buf); //写数据 写fifo2 memset(buf, 0, sizeof(buf)); fgets(buf, sizeof(buf), stdin); //从屏幕的stdin标准输入(标准输入也有缓冲区) 获取128个字节并装到buf里 //将从标准输入得到的数据写到fifo里 int ret = write(fdw, buf, strlen(buf)); if (ret == -1) { perror(&#34;write:&#34;); return -1; } } close(fdw); close(fdr); return 0; }

二、与文件属性相关的操作函数
acess判断文件的权限(或文件是否存在) chmod修改文件的权限 chown修改文件的所有者或所在组 truncate用于缩减或扩展某个文件的大小
/* #include &lt;unistd.h&gt; int access(const char *pathname, int mode); 作用:判断某个文件是否有某个权限(通过当前进程是否能访问某个文件来判断) 或者判断文件是否存在 参数： 文件名 mode：待判断的当前进程对这个文件权限 F_OK(用于检查文件是否存在) R_OK(是否可读) W_OK(是否可写) X_OK(是否可执行) 返回值: 成功返回0 失败返回-1 \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; //perror int main() { int ret = access(&#34;a.txt&#34;, F_OK); //判断 a.txt是否存在 if (ret == -1) { perror(&#34;file not exist&#34;); } return 0; } // gcc access.c -o access /* #include &lt;sys/stat.h&gt; int chmod(const char *pathname, mode_t mode); 用于修改当前进程对pathname文件的权限 参数: 文件名 mode_t mode 需要修改的权限 给定相应的宏 让这个进程拥有对文件的处理的相应权限 也可以像例子中那样直接给个八进制数0775 S_ISUID (04000 八进制) set-user-ID (set process effective user ID on execve(2)) S_ISGID (02000) set-group-ID (set process effective group ID on execve(2); mandatory locking, as described in fcntl(2); take a new file&#39;s group from parent directory, as described in chown(2) and mkdir(2)) S_ISVTX (01000) sticky bit (restricted deletion flag, as described in unlink(2)) S_IRUSR (00400) read by owner S_IWUSR (00200) write by owner S_IXUSR (00100) execute/search by owner (&#34;search&#34; applies for directories, and means that entries within the directory can be accessed) S_IRGRP (00040) read by group S_IWGRP (00020) write by group S_IXGRP (00010) execute/search by group S_IROTH (00004) read by others 返回值: 成功返回0 失败返回-1 \*/ #include &lt;sys/stat.h&gt; int main() { //-rw-rw-r-- 664 原a.txt权限---&gt;-rwxrwxr-x 775 int ret = chmod(&#34;a.txt&#34;, 0775); if (ret == -1) { return -1; //fail } return 0; } /* #include &lt;unistd.h&gt; int chown(const char *pathname, uid_t owner, gid_t group); uid_t owner 待改为哪个用户id所有这个文件 gid_t group 待改为哪个组id所有这个文件 vim /etc/passwd 当中写了所有的用户 wen:x:1000(用户id):1000(组id):wen,,,:/home/wen:/bin/bash vim /etc/group 当中写了所有的组 wen:x:1000(组id): sudo useradd 用户名 来添加用户 id 用户名 来查看用户的uid与gid uid=1000(wen) gid=1000(wen) 组=1000(wen 组名) 要想通过chown修改文件的所有者和所有组 在编译完后 需要 sudo ./可执行文件 才有权限去修改!!!!!!!!! \*/ #include &lt;sys/stat.h&gt; int main() { int ret = chown(&#34;a.txt&#34;, 1000, 1000); if (ret == -1) { return -1; //fail } return 0; } /* #include &lt;unistd.h&gt; #include &lt;sys/types.h&gt; int truncate(const char *path, off_t length); 用于缩减或拓展文件的大小 参数： 文件路径 length 文件最终的大小(文件经过这个函数后就直接变这么大了) 如需清空文件，length设置为0 这个大小大于当前大小 则在文件尾添加一系列空字节 小于则将超出部分删掉 返回值： 成功返回0 失败返回-1并设置errno 1 EACCESS 参数path所指定的文件无法存取 2 EROFS 欲写入的文件存在于只读文件系统内 3 EFAULT 参数path指针超出可存取空间 4 EINVAL 参数path包含不合法字符 5 ENAMETOOLONG 参数path太长 6 ENOTDIR 参数path路径并非一目录 7 EISDIR 参数path指向一目录 8 ETXTBUSY 参数path所指的文件为共享程序，而且正被执行中 9 ELOOP 参数path 有过多符号连接问题。 10 EIO I/O存取错误 \*/ #include &lt;unistd.h&gt; #include &lt;sys/types.h&gt; int main() { int ret = truncate(&#34;a.txt&#34;, 20); //将a.txt变为20个字节 if (ret == -1) { return -1; //fail } return 0; } 三、目录操作函数
/* #include &lt;sys/stat.h&gt; #include &lt;sys/types.h&gt; int mkdir(const char *pathname, mode_t mode); man 2 mkdir man 1 mkdir为linux系统命令说明 创建一个目录 参数: pathname 想要创建的目录的路径 mode mode_t 8进制数代表这个目录的权限 具体可看use_chmod.c中对mode的详细解释 这里跟那边是一样的 返回值： 成功返回0 失败返回-1 \*/ #include &lt;sys/stat.h&gt; #include &lt;sys/types.h&gt; int main() { int ret = mkdir(&#34;aaa&#34;, 0777); //在当前路径下再生成 /aaa 相当于生成./aaa的路径 //虽然指定777但实际生成的为775(因为与umask掩码相关 具体可看use_open.c的说明) //注意目录只有拥有可执行权限 我们才能进入这个目录中 比如用户对这个文件(目录)拥有可执行文件 用户才能进入到这个路径下 if (ret == -1) { return -1; //fail } return 0; } #include &lt;unistd.h&gt; int rmdir(const char *pathname);//用于删除空目录 目录内有内容就删不掉了 #include &lt;stdio.h&gt; int rename(const char *oldpath, const char *newpath);//将oldpath用newpath字符串替换 rename(“aaa”,”bbb”);//将aaa用bbb替代 /* #include &lt;unistd.h&gt; int chdir(const char *path);//cd 改变(当前进程所处)当前的工作目录为path(绝对路径) 成功返回0，失败返回-1 进程的初始工作目录为 你在哪个路径下将它启动 它的初始工作路径就在那 #include &lt;unistd.h&gt; char *getcwd(char *buf, size_t size);//pwd 获得当前的工作的绝对路径(当前进程所处) 用buf传出路径字符串 返回的是buf的首地址，为了方便直接输出buf字符串 \*/ #include &lt;unistd.h&gt; #include &lt;sys/types.h&gt; //flags宏在这个头文件 #include &lt;sys/stat.h&gt; //flags宏在这个头文件里也有 #include &lt;fcntl.h&gt; //函数声明在这个头文件中 #include &lt;stdio.h&gt; //perror #include &lt;unistd.h&gt; //close //gcc use_cd_pwd.c -o cd int main() { //获取当前工作目录 char buf[128]; printf(&#34;当前的工作路径是：%s
&#34;, getcwd(buf, sizeof(buf))); // /home/wen/lesson11 //修改工作目录 int ret = chdir(&#34;/home/wen/lesson10&#34;); if (ret == -1) { perror(&#34;cd fail&#34;); return -1; //fail } //创建新的文件 int fd = open(&#34;chdir210.txt&#34;, O_CREAT | O_RDWR, 0664); //生成了/home/wen/lesson10/chdir210.txt if (ret == -1) { perror(&#34;create fail&#34;); return -1; //fail } close(fd); char buf2[128]; printf(&#34;当前的工作路径是：%s
&#34;, getcwd(buf2, sizeof(buf2))); // /home/wen/lesson10 return 0; } 四、目录遍历
/* 读取目录下普通文件的个数 man 3 标准c #include &lt;sys/types.h&gt; #include &lt;dirent.h&gt; DIR *opendir(const char *name); 获取path子目录下的所由文件和目录的列表，如果path是个文件(或其他失败场景) 则返回值为NULL 正常返回目录流的第一个进入点 typedef struct __dirstream DIR; __dirstream为目录流类型 其内容对用户不开放看不到其中内容 #include &lt;dirent.h&gt; struct dirent *readdir(DIR *dirp); dirp 为 opendir返回的结果 读取目录中的数据 每调用一次DIR内部指针就自动指向drip中的下个实体 返回参数dirp 目录流的下个目录进入点 信息保存在结构体struct dirent *中 struct dirent { ino_t d_ino; 此目录进入点的inode节点编号 Inode number off_t d_off; 目录文件开头到此目录进入节点的偏移 Not an offset; see below unsigned short d_reclen; d_name文件名的实际长度(占了[256]中的几个 到底文件名为多少个字符) 不包含NULL字符 Length of this record unsigned char d_type; d_name文件的类型 Type of file; not supported by all filesystem types char d_name[256]; 文件名 Null-terminated filename }; 其中d_name文件的类型d_type有如下几种 DT_BLK 块设备 DT_CHR 字符设备 DT_DIR 目录 DT_LNK 软连接 DT_FIFO 管道 DT_REG 普通文件 DT_SOCK 套接字 DT_UNKNOWN 未知 当读取到末尾(不会设置errno或失败(会设置errno) 返回NULL #include &lt;sys/types.h&gt; #include &lt;dirent.h&gt; int closedir(DIR *dirp); 关闭目录 \*/ #include &lt;sys/types.h&gt; #include &lt;dirent.h&gt; #include &lt;stdio.h&gt; #include &lt;string.h&gt; //读取某个目录下(嵌套直到最深)所有普通文件的个数 // ./count.out 目录路径 void getFileNum(const char *path, int *res); int main(int argc, char *argv[]) { if (argc &lt; 2) { //一般一定会有一个参数 是可执行文件的路径 //再加上跟上的文件名 一共至少为两个参数 模拟才会生效 //所以这里判断一下参数个数小于2个就return printf(&#34;%s filename
&#34;, argv[0]); //argv[0]为执行文件的路径 return -1; } int ret = 0; //普通文件的个数 getFileNum(argv[1], &amp;ret); printf(&#34;共有普通文件%d个
&#34;, ret); return 0; } //递归 遍历所有子目录(含子目录的子目录...) 统计其中普通文件的个数 void getFileNum(const char *path, int *res) { // 打开目录 DIR *dir = opendir(path); if (dir == NULL) { perror(&#34;dir is null&#34;); return; } struct dirent *ptr; //循环读取子目录 while ((ptr = readdir(dir)) != NULL) //只要没读到末尾(不为NULL) 或出错 就一直循环下去 每调用一次DIR内部指针就自动指向drip中的下个实体 { /* code */ //获取名称 不能将./ ../算入子目录中 char *dname = ptr-&gt;d_name; if (strcmp(dname, &#34;.&#34;) == 0 || strcmp(dname, &#34;..&#34;) == 0) //过滤. .. strcmp==0说明两个字符串相同 { continue; } //判断是否是普通文件res++ 还是目录(递归调用) if (ptr-&gt;d_type == DT_DIR) //是目录 注意dname仅仅是目录的名字而非完整的路径 { //opendir的path要求是完整路径所以递归调用时传的path也要是完整路径 char newpath[256]; sprintf(newpath, &#34;%s/%s&#34;, path, dname); //拼接得到dname对应文件的完整路径 要s/s getFileNum(newpath, res); //递归调用 遍历子目录内的文件 } else if (ptr-&gt;d_type == DT_REG) //是普通文件 { (*res)++; //要括号*优先级不高 } } closedir(dir); return; } 五、文件描述符重定向
/* #include &lt;unistd.h&gt; int dup(int oldfd); 系统调用 传入被拷贝的描述符 用未被使用的数值最小的文件描述符作为新的描述符 注意拷贝的是文件描述符指向的FILE结构体的内容 而非真的拷贝文件！！！！ 新的描述符和老的描述符指向的是同一个文件！！！ 如果拷贝成功返回这个新的的描述符 失败返回-1并设置errno \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;fcntl.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;string.h&gt; int main() { int fd = open(&#34;a.txt&#34;, O_RDWR | O_CREAT, 0664); //创造新的文件a.txt 因为fd 1,2为流的fd已占用 这个新的fd因该是3 int newfd = dup(fd); if (newfd == -1) { perror(&#34;dup fail&#34;); return -1; } print(&#34;fd:%d newfd:%d 
&#34;, fd, newfd); //fd:3 newfd:4 //关闭fd 用newfd向写a.txt写内容 成功 证明dup后 newfd和fd指向的是同一个文件 close(fd); char *str = &#34;hello&#34;; int ret = write(newfd, str, strlen(str)); if (ret == -1) { perror(&#34;write fail&#34;); return -1; } close(newfd); return 0; } /* #include &lt;unistd.h&gt; int dup2(int oldfd, int newfd);//功能和dup类似 用于重定向文件描述符 oldfd指向a.txt newfd指向b.txt 在调用函数成功后将newfd-&gt;b.txt关闭并且再让newfd指向a.txt oldfd必须是一个有效的 真实指向文件的描述符 如果是个无效的文件描述符 并不会做关闭newfd操作 并且返回-1设置errno 如果oldfd和newfd值相同 相当于什么都没做 直接返回newfd并且不会做关闭newfd操作 正常返回的就是newfd \*/ #include &lt;unistd.h&gt; #include &lt;stdio.h&gt; #include &lt;fcntl.h&gt; #include &lt;sys/types.h&gt; #include &lt;sys/stat.h&gt; #include &lt;string.h&gt; int main() { int oldfd = open(&#34;a.txt&#34;, O_RDWR | O_CREAT, 0664); //创造新的文件a.txt 因为fd 1,2为流的fd已占用 这个新的fd因该是3 if (oldfd == -1) { perror(&#34;open fail&#34;); return -1; } int newfd = open(&#34;b.txt&#34;, O_RDWR | O_CREAT, 0664); //创造新的文件a.txt 因为fd 1,2为流的fd已占用 这个新的fd因该是3 if (newfd == -1) { perror(&#34;open fail&#34;); return -1; } print(&#34;oldfd:%d newfd:%d 
&#34;, oldfd, newfd); int retfd = dup2(oldfd, newfd); print(&#34;oldfd:%d newfd:%d 
&#34;, oldfd, newfd); if (retfd == -1) { perror(&#34;dup2 fail&#34;); return -1; } //oldfd与newfd在dup2后指向的都是a.txt 下面用newfd来验证一下 close(oldfd); char *str = &#34;I&#39;m newfd&#34;; int ret = write(newfd, str, strlen(str)); if (ret == -1) { perror(&#34;write fail&#34;); return -1; } close(newfd); return 0; } 六、fcntl复制文件描述符 设置/获取文件的状态标志
/* fcntl复制文件描述符 设置/获取文件的状态标志 #include &lt;unistd.h&gt; #include &lt;fcntl.h&gt; int fcntl(int fd, int cmd, ... arg );//...表示可变参数 可写也可不写 fd 被操作的文件描述符 cmd 对文件描述符做什么操作 对fd文件做cmd操作 cmd: F_DUPFD 复制文件描述符 F_GETFL 获取指定文件描述符的文件状态flag 文件状态flag在学习open的时候有提到 flags:对文件的操作权限设置 以及其他的一些设置 O_RDONLY,O_WRONLY,O_RDWR 三个宏分别对应只读,只写,读写。 这三个设置是互斥的，1次open只能选1个必选项。 O_APPEND 不覆盖在尾部继续追加 O_CREAT 如果文件不存在则创建新文件 等的可选项 在有多个选项时通过|按位或连接如O_RDWR | O_CREAT flags是int型占4个字节 为32位其中每一位就是一个标志位每一位代表一种情况(1种标记 可读 可写 可读写 创建新文件) F_SETFL 设置指定文件描述符的文件状态flag(O_DSYNC and O_SYNC文件状态无法通过setfl改变) O_RDONLY,O_WRONLY,O_RDWR 三个宏分别对应只读,只写,读写。 这三个设置是互斥的，1次open只能选1个必选项， 这三个必选项是无法修改的即无法通过F_SETFL设置！！！ 并且与文件创建有关的状态 O_CREAT O_EXCL O_NOCTTY O_TRUNC都是无法设置的！！！ 可选项 O_APPEND 不覆盖在尾部继续追加 O_NONBLOCK 非阻塞 等是可设置的 这里的阻塞与非阻塞描述的是函数调用的行为， 所谓阻塞方式block，就是进程或是线程执行到这些函数时必须等待某个事件的发生，如果事件没有发生，进程或线程就被阻塞，函数不能立即返回。 所谓非阻塞方式non-block，就是进程或线程执行此函数时不必非要等待事件的发生，一旦执行肯定返回，以返回值的不同来反映函数的执行情况， 如果事件发生则与阻塞方式相同，若事件没有发生则返回一个代码来告知事件未发生，而进程或线程继续执行，所以效率较高 复制传入的fd,并用未被使用的数值最小的文件描述符作为新的描述符 新描述符和fd指向的是同一文件 如果复制成功 返回值就是新的描述符 \*/ #include &lt;unistd.h&gt; #include &lt;fcntl.h&gt; #include &lt;stdio.h&gt; int main() { //1复制文件描述符 //int fd = open(&#34;1.txt&#34;, O_RDONLY); // int ret = fcntl(fd, F_DUPFD); //返回复制的那个新的描述符 这个新的描述符和fd都是指向1.txt的 //2修改和获取文件状态flag int fd = open(&#34;1.txt&#34;, O_RDWR); if (fd == -1) { perror(&#34;open fail&#34;); return -1; } //当前是不能写文件的 下面先修改文件状态给flag加入O_APPEND 之后就能在文件尾添加 int flag = fcntl(fd, F_GETFL); //先获取当前文件描述符的状态 //如果直接给fcntl(fd, F_SETFL,O_APPEND); 那么之前的状态O_RDWR会被直接覆盖 当前线程对此文件不再可读写 //flag | O_APPEND 在原基础上追加O_APPEND int ret = fcntl(fd, F_SETFL, flag | O_APPEND); //F_SETFL 失败返回-1 成功返回0 close(fd); return 0; }

6 一些补充
1 const
用const修饰的函数内成员变量全部变为const只能读
对象为const对象(成员变量不可写) 调用const函数(函数内部保证不写成员变量) ok
非cosnt对象 调用const函数 ok
非const对象 调用非const函数 ok
const对象 调用非const函数 fasle!!!!
const对象只能调用const修饰的函数
注意c++规定当成员函数的const版本和非const版本同时存在，const对象只能调用const版本的成员函数，非const对象只能调用非const版本的成员函数。
string的[]重载 有两个函数&ndash;const函数修饰 能作为重载的依据，这也是为什么两个函数的形参类型和个数一样，但是可以共存
上面的[]的重载是在用作右值的时候 比如 char c = s[1];
此时是只读字符串内容所以加上了const修饰，此时的s为常量或非常量都ok&mdash;普通变量=同类型的引用变量是ok的
下面的[]的重载是在用作左值的时候 比如 s[1] = ‘c’;
此时的s一定为非常量
此时需要写s的内容所以[]返回的是个char引用，并且如果s这个字符串是由其他字符串拷贝得到的，在调用左值[]时会发生 写时拷贝 会为其申请属于它自己的堆上内存，并且初始化自己这块堆上内存的reference counting引用计数为1
c++ string是内存共享的并且是写时拷贝(copy on write)
通常，string类中必有一个私有成员，其是一个char*，用户记录从堆上分配内存的地址，其在构造时分配内存，在析构时释放内存。
因为是从堆上分配内存，所以string类在维护这块内存上是格外小心的，string类在返回这块内存地址时，只返回const char*，也就是只读的，如果你要写，也只能通过string提供的方法进行数据的改写。
string str1 = &ldquo;hello world&rdquo;;
string str2 = str1;
string str3 = str2;
str1,str2,str3都是拷贝构造得到的，其内部的char指针指向的是同一块堆上内存。
printf (&quot;\tstr1 的地址: %x\n&quot;, (unsigned int)str1.c_str() );
printf (&quot;\tstr2 的地址: %x\n&quot;, (unsigned int)str2.c_str() );
printf (&quot;\tstr3 的地址: %x\n&quot;, (unsigned int)str3.c_str() );
str1 的地址: 83f9017
str2 的地址: 83f9017
str3 的地址: 83f9017
先修改str[3]内容，但是不能直接修改str3 char的堆上内容因为此时str1,str2还共享着这块内存，所以需要重新为str3 char开辟一块新的堆上内存并拷贝原来的char堆上内存然后再依照索引修改对应内容。此后str1 char堆上内存被str2共享，str3 char指向其自己的堆上内存&ndash;str[2]内容修改发生的变化同理
str3[1]=&lsquo;a&rsquo;;
str2[1]=&lsquo;w&rsquo;;
str1[1]=&lsquo;q&rsquo;;
printf (&ldquo;通过写时拷贝之后:\n&rdquo;);
printf (&quot;\tstr1 的地址: %x\n&quot;, (unsigned int)str1.c_str() );
printf (&quot;\tstr2 的地址: %x\n&quot;, (unsigned int)str2.c_str() );
printf (&quot;\tstr3 的地址: %x\n&quot;, (unsigned int)str3.c_str() );
通过写时拷贝之后:
str1 的地址: 83f9017
str2 的地址: 83f9054
str3 的地址: 83f9034
在str3,str2修改开辟新的堆上内存时会多申请1个count变量,char*指向的头4个字节,(str1也有这个变量)，这个count就是引用计数
在初始
string str1 = &ldquo;hello world&rdquo;;
string str2 = str1;
string str3 = str2;
时str1 char*指向内存的头4个字节保存的引用计数为3
str3[1]=&lsquo;a&rsquo;;
str2[1]=&lsquo;w&rsquo;;
str1[1]=&lsquo;q&rsquo;;
后str1 char*指向内存的头4个字节保存的引用计数为1
